const p=(text,...sources)=>({text,sources});
const sec=(id,title,...paragraphs)=>({id,title,paragraphs});
const supplier=(name,offering,note,...sources)=>({name,offering,note,sources});
const alternative=(name,description,tradeoff,...sources)=>({name,description,tradeoff,sources});
const term=(term,definition)=>({term,definition});
const flight=(...ids)=>ids.map(id=>'flight:'+id);
const articles={
 '01.01':{
  summary:'Accelerator boards perform the matrix arithmetic and memory access behind the data center’s AI workloads. Their cold plates or local heat spreaders form the first part of the path that carries almost all of that electrical power away as waste heat.',
  sections:[
   sec('purpose','The computing payload',
    p('An accelerator is a highly parallel processor. A host prepares work and moves inputs to it; the accelerator repeatedly reads model weights and working data, performs arithmetic, and returns results. Training, inference and scientific computation stress these resources differently. A board that is fast at one precision or batch size is not automatically fast at another. The workload controls therefore matter as much as the chip count.','flight-a100','flight-tpu'),
    p('For this mission the useful output is computation delivered to a customer. Peak arithmetic is only a ceiling. Memory capacity determines which models fit; memory bandwidth often limits small-batch token generation; interconnects matter when a job spans several accelerators. Power availability, temperature and the scheduled workload determine how much of the installed capability can actually be used.')),
   sec('operation','From silicon to the radiator',
    p('The thermal path begins inside the semiconductor package, then crosses an interface into a spreader or cold plate. Contact resistance produces a temperature rise even when the metal looks perfectly joined in the viewer. The next path depends on the selected architecture: a local passive radiator, a circulating liquid loop, or an actively lifted hot-side loop. Vacuum removes the option of rejecting heat to ambient air with ordinary server fans.'),
    p('A complete compute tray also needs regulators, hosts, memory and communication interfaces. NVIDIA’s DGX manual is a useful anatomy lesson because it lists these supporting elements separately from its GPUs. Its rack chassis, cooling arrangement and maximum server power are terrestrial reference boundaries, not the dimensions or qualification of the workbench tray.','flight-dgx')),
   sec('engineering','What sets the design',
    p('Size the thermal contact for the hottest device, then check the combined tray load, supply transients and the paths shared with neighboring trays. More boards increase service potential only if power conversion, heat transport, storage and communications grow with them. A dense layout can save structure and cable length while making local heat flux and access for assembly more demanding.'),
    p('Radiation response belongs to the actual devices and operating conditions. Error correction, checkpointing and restart strategies address different consequences from destructive device effects. An ISS computer experiment is useful evidence for its tested accommodation; it does not establish that the same assembly will operate exposed to vacuum in a different orbit.','flight-rha','flight-hpe'))
  ],
  suppliers:[supplier('NVIDIA','A100 and DGX H100/H200 references','Commercial accelerator and server documentation used to understand performance and system boundaries; no flight qualification is implied.','flight-a100','flight-dgx'),supplier('Google','TPU v6e / Trillium','An alternative accelerator architecture and interconnect reference, not a purchasable flight tray specified by this study.','flight-tpu')],
  alternatives:[alternative('GPU, TPU or another accelerator architecture','Choose against the actual model, precision, memory capacity and software stack.','Changing the chip also changes host software, data movement, packaging and qualification work.','flight-a100','flight-tpu'),alternative('Distribute compute close to radiator surfaces','Shorten heat-transport paths by spreading the payload across modules.','More distributed modules require electrical/data routing and structural accommodation.','flight-redwire-thermal')],
  inspection:['Follow the board-to-plate contact, then open the related host and thermal-transport pages. The decorative packages do not identify a specific purchased chip.'],
  terms:[term('HBM','High-bandwidth memory placed close to an accelerator.'),term('Heat flux','Heat flow per unit contact or surface area.'),term('Checkpoint','A saved computation state from which work can resume.')],
  relatedIds:flight('01.02','01.04','02.03','03.01','03.02'),sourceIds:['flight-a100','flight-dgx','flight-tpu','flight-hpe','flight-rha','flight-redwire-thermal']
 },
 '01.02':{
  summary:'The host electronics turn a collection of accelerators into a usable computer. CPUs, working memory, boot devices and control interfaces schedule jobs and manage data, while the tray carrier holds the electronics and conducts their heat into the spacecraft.',
  sections:[
   sec('purpose','The rest of the computer',
    p('An AI accelerator does not normally boot an entire service by itself. The host starts the operating system, loads drivers and model weights, accepts work, prepares batches and handles results. Host memory may hold data that is too large or too slow-changing to keep in accelerator memory. A processor can have ample arithmetic capacity yet remain underused if its host cannot supply work quickly enough.'),
    p('A server reference is valuable precisely because it exposes the supporting equipment. The DGX H100/H200 guide separates CPUs, system memory, GPU interconnect, network adapters, boot storage and data-cache drives. Those functions must still exist somewhere in an orbital data center even if their physical packaging is completely redesigned.','flight-dgx')),
   sec('operation','Packaging is an engineering function',
    p('The tray carrier provides mounting datums, connector support and a thermal route. In a conduction-cooled arrangement, board retainers and contact surfaces help move heat to a structural wall or cold plate. Components with different heights, expansion coefficients and heat loads need deliberate interfaces; a visually neat stack is not enough to establish a working contact-pressure or temperature budget.'),
    p('Assembly access matters before launch. Technicians need to install boards, mate connectors, inspect terminations and reach fasteners without disturbing adjacent hardware. Once the tray is installed, launch vibration and thermal cycling act on the same joints. Verification checks both functional behavior and the environmental loads for the specific configuration.','flight-gevs')),
   sec('engineering','Host capacity and spacecraft authority',
    p('Host capacity is sized around workload preparation, memory footprint and communication traffic rather than by copying an accelerator-to-CPU ratio from an unrelated server. More host resources can prevent expensive accelerators from waiting, but those resources consume electrical power and add heat even when no customer job is running.'),
    p('Payload hosts should have a clearly defined relationship with flight avionics. A customer job needs access to data and computing resources; it should not implicitly become the authority that controls spacecraft power, pointing or propulsion. HPE’s Spaceborne Computer reports are useful examples of commercial computing in space, while the flight-avionics literature describes the different responsibilities of the spacecraft control system.','flight-hpe','flight-avionics'))
  ],
  suppliers:[supplier('Hewlett Packard Enterprise','Spaceborne Computer-2','A commercial-server experiment hosted on the ISS; useful operational evidence, with different pressure, cooling and mission boundaries from this spacecraft.','flight-hpe'),supplier('NVIDIA','DGX H100/H200 server architecture','A complete-system reference for understanding the supporting host resources around accelerators.','flight-dgx')],
  alternatives:[alternative('One host per tray','Keep each tray an independently addressable compute unit.','More hosts add idle power and software instances, while localizing workload and hardware boundaries.'),alternative('Shared hosts for several accelerator trays','Consolidate host resources and reduce repeated support hardware.','The shared host and its interconnect can become throughput, availability and integration bottlenecks.','flight-dgx'),alternative('Conduction-cooled modular electronics','Use card carriers and controlled thermal interfaces.','Packaging flexibility must be reconciled with connector standards and heat-transfer capacity.','flight-fsm')],
  inspection:['Look at the carrier and mounting surfaces, then select Installed to see the tray’s place in the structure.'],
  terms:[term('Host','The processor and system software coordinating accelerator work.'),term('Datum','A reference surface or point used to locate hardware accurately.')],
  relatedIds:flight('01.01','01.03','01.04','07.01','08.01'),sourceIds:['flight-dgx','flight-hpe','flight-fsm','flight-avionics','flight-gevs']
 },
 '01.03':{
  summary:'Solid-state storage holds models, input data, checkpoints and completed results between transfers. It decouples the timing of computation from the timing of ground contact, so the spacecraft can keep useful work and recover it when a link is available.',
  sections:[
   sec('purpose','Capacity is only one requirement',
    p('A storage budget has several occupants: software and model files, working datasets, retained customer artifacts, temporary checkpoints and the queue waiting for downlink. Free space needs a margin because new results may arrive while a contact is delayed or a large model is being installed. Raw advertised capacity is therefore different from the capacity available to mission work.'),
    p('Bandwidth and latency are separate from capacity. Loading a model is a sustained read; checkpointing can create a burst of writes; small metadata operations create a different access pattern. The internal network, host interface and software may become the limit before the flash devices do. An SSD data sheet should be read with its workload and test conditions, rather than reduced to a single speed.','flight-micron')),
   sec('operation','How a flash-storage subsystem behaves',
    p('Flash stores data without continuous power, but its controller still performs mapping, error correction and internal maintenance. Writing new information can involve more internal activity than the host-requested byte count suggests. Lifetime planning therefore considers total writes, spare capacity and the expected temperature and power history. Checkpoints that are useful for recovery can also dominate the write budget.'),
    p('A flight installation includes the drive, a carrier, connectors, thermal paths and data-integrity measures. Curtiss-Wright’s FSM-C illustrates the distinction: it is a conduction-cooled storage carrier using a commercial drive. That carrier is a packaging precedent; its interface and environment are not automatically the same as the NVMe modules used in the study.','flight-fsm')),
   sec('engineering','Preserving useful work',
    p('Separate the queues that support immediate service from long-lived artifacts. A voice or text service may need modest output bandwidth, while a model checkpoint or training dataset can be far larger. The relevant test is whether writes, retention and contact opportunities balance over time. A fast link does not empty a queue when the station is below the horizon.'),
    p('Data integrity also depends on the controller, firmware, host software and radiation response. Replication and checksums protect particular failure modes; keeping two copies on devices sharing the same vulnerable controller is a different boundary from independent copies. HPE’s documented ISS deployment with KIOXIA flash is a useful operational reference, not a qualification of every commercial SSD for free flight.','flight-hpe','flight-rha'))
  ],
  suppliers:[supplier('Micron','7450 NVMe SSD family','Commercial storage performance and capacity reference. The installed carrier and flight environment remain separate design work.','flight-micron'),supplier('Curtiss-Wright','FSM-C storage carrier','A rugged conduction-cooled packaging comparison with SATA storage, not a drop-in substitute for an NVMe flight module.','flight-fsm'),supplier('KIOXIA / HPE','ISS Spaceborne Computer-2 storage','Documented flash hardware used aboard an ISS-hosted server experiment.','flight-hpe')],
  alternatives:[alternative('Local storage on every compute tray','Keep frequently used models and working files close to their processors.','Repeated copies consume capacity and require version synchronization.'),alternative('Shared storage pool','Concentrate capacity and simplify some data-management tasks.','Fabric bandwidth and shared-control availability become more important.','flight-quantum'),alternative('Reduce or schedule generated data','Choose checkpoint cadence, compression and retention according to the mission.','Recomputation and recovery time can increase when fewer intermediate states are retained.')],
  inspection:['The enclosure represents the installed storage allocation. Capacity and write endurance are properties of selected devices and configuration, not the size of the rendered box.'],
  terms:[term('DWPD','Drive writes per day, an endurance measure tied to capacity and warranty conditions.'),term('Goodput','Useful delivered data rate after protocol overhead and retransmissions.')],
  relatedIds:flight('01.01','01.04','05.02','05.03'),sourceIds:['flight-micron','flight-fsm','flight-hpe','flight-rha','flight-quantum']
 },
 '01.04':{
  summary:'The payload fabric moves data among accelerator trays, hosts, storage and communication terminals. It is the internal network that lets the installed computing hardware cooperate and lets useful results reach the spacecraft’s downlink systems.',
  sections:[
   sec('purpose','Several different kinds of traffic',
    p('An orbital data center carries more than one traffic pattern. Model loading moves large files toward accelerators; distributed training exchanges intermediate values repeatedly; inference requests may be small but sensitive to delay; checkpoint writes can create bursts. These demands share links unless the architecture deliberately separates them. A port rate alone does not describe the throughput available to every flow.'),
    p('The payload network and the spacecraft command network also serve different purposes. Flight controls need predictable access to commands and telemetry even when customer traffic is heavy. The interface between them can transfer health and scheduling information without turning the high-throughput payload network into the sole route for basic spacecraft control.','flight-avionics')),
   sec('operation','Links, switches and bottlenecks',
    p('A link connects endpoints; a switch selects the onward path; the protocol determines how data is framed, paced, checked and recovered. A network can have many fast ports and still be oversubscribed across a shared uplink. Buffering can absorb bursts but cannot cure a sustained mismatch between arrivals and service. Latency includes waiting in queues as well as signal travel and processing.'),
    p('NVIDIA’s Quantum-2 manual is a concrete high-performance computing reference. ESA’s SpaceWire introduction describes a very different onboard-network tradition with links, routers and standardized protocols. Both are useful to learn from, but they support different rate, device, software and mission assumptions. One should not be called a compatible replacement for the other merely because both carry bits.','flight-quantum','flight-spacewire')),
   sec('engineering','What to compare',
    p('Start with the traffic matrix: which devices exchange how much data, how often, and with what timing requirements? Then compare full-duplex bandwidth, aggregate switch capacity, route redundancy, error handling, connector count, power and heat. In distributed AI work, the pattern of collective exchanges can matter more than the maximum point-to-point benchmark.'),
    p('Copper and optical interconnects trade mass, reach, electrical isolation, connector complexity and transceiver power. Mechanical routing matters too: harnesses need clearance around service panels and deployment joints. The workbench’s allocation describes the installed fabric function; its shared electronics geometry does not establish a complete switch schematic or a qualified network topology.'))
  ],
  suppliers:[supplier('NVIDIA','Quantum-2 / QM97XX InfiniBand switches','A terrestrial high-bandwidth network reference with detailed port and interface documentation.','flight-quantum'),supplier('ESA / ECSS ecosystem','SpaceWire onboard links and routers','A standards-based spacecraft-network reference; individual supplier and throughput choices require a separate selection.','flight-spacewire')],
  alternatives:[alternative('Ethernet-based fabric','Use a broad networking ecosystem and standard host interfaces.','Performance depends on congestion control, switch capacity and the chosen transport; application timing still needs measurement.','flight-dgx'),alternative('InfiniBand or accelerator-specific interconnect','Optimize for tightly coupled distributed compute.','Software, adapters, switching and physical integration become tied to the selected ecosystem.','flight-quantum','flight-tpu'),alternative('Separate service and payload networks','Reserve spacecraft control paths from customer data traffic.','Bridges, monitoring and additional interfaces add integration work.','flight-spacewire','flight-avionics')],
  inspection:['Follow the related storage, host and terminal pages to see the endpoints. The viewer may show a shared electronics package rather than an independently resolved switch.'],
  terms:[term('Oversubscription','More potential input traffic than a shared output path can carry.'),term('Collective','A coordinated data exchange involving multiple computing devices.')],
  relatedIds:flight('01.01','01.02','01.03','05.02','05.03','07.05','08.01'),sourceIds:['flight-quantum','flight-spacewire','flight-dgx','flight-tpu','flight-avionics']
 },
 '02.01':{
  summary:'Solar wings convert sunlight into electrical power and deploy enough collecting area to support the computing load. The cells, blanket or panel substrate, supporting booms and electrical interconnects work together; cell efficiency alone does not determine useful spacecraft power.',
  sections:[
   sec('purpose','From sunlight to a working power supply',
    p('A solar cell produces current and voltage when illuminated. Cells are placed in series to build voltage and in parallel to build current. The array connects to power-conditioning electronics that match this source to the spacecraft bus and battery. Its operating point changes with illumination, temperature, aging and the electrical load.','flight-power'),
    p('The mission needs energy over an orbit as well as power at an instant. While sunlit, the wings may need to supply the active payload and replace energy used during eclipse. Attitude affects projected area; shadows from the spacecraft or other appendages can reduce usable output. The end-of-life power budget must include the chosen degradation and delivery assumptions.')),
   sec('operation','Cells and deployable structure',
    p('Multijunction cells use several semiconductor junctions to collect different portions of the solar spectrum. Silicon remains a meaningful comparison where cost, area and supply strategy dominate. Spectrolab’s documentation gives actual cell-family examples and end-of-life conditions. Those cell results do not by themselves establish an entire wing’s output or mass.','flight-spectrolab'),
    p('A wing must fit inside the launch envelope, survive launch loads and then become a stable deployed structure. Redwire’s ROSA uses a flexible blanket with rollable composite booms and strain energy for deployment. The workbench can represent different wing counts and deployment layouts; a similar silhouette does not make every modeled drum or boom an exact ROSA part.','flight-rosa','flight-rosa-nasa')),
   sec('engineering','Area brings consequences',
    p('Increasing area can solve a power deficit while increasing inertia, drag torque, structural flexibility and the wiring distance back to the bus. Long flexible wings can interact with pointing maneuvers. Their root mechanisms must carry mechanical loads and pass electrical power across moving interfaces. These couplings explain why arrays belong in both the power and attitude-control discussions.'),
    p('Compare the full wing at the required life: delivered power, stowed envelope, deployed stiffness, mass, temperature limits and integration constraints. A source advertised at beginning-of-life normal incidence will not continuously deliver that rating through eclipse or off-pointing. The selected power architecture also limits how much generated power can pass through its MPPT channels and rotary circuits.'))
  ],
  suppliers:[supplier('Redwire','ROSA solar-array family','A real rollable-array product and deployment reference. The workbench’s larger or differently arranged wings need their own structural and electrical evidence.','flight-rosa'),supplier('Boeing Spectrolab','Multijunction cells and space panels','Cell and panel supplier examples; substrate, cell choice and mission conditions determine the integrated result.','flight-spectrolab')],
  alternatives:[alternative('Rigid hinged panels','Use panel stiffness and discrete hinge lines to deploy a wing.','The stowed stack, hinge count and panel mass differ from a rolled blanket.','flight-power'),alternative('Rollable blanket arrays','Pack a large collecting surface into a compact stowed form.','Boom behavior, blanket tension, deployment dynamics and current routing need coordinated design.','flight-rosa'),alternative('Body-mounted cells','Avoid a major deployable mechanism for a small power demand.','Available area and changing orientation usually constrain sustained computing power.','flight-power')],
  inspection:['Use Deploy & stow to follow the support structure and electrical path. Compare the collecting face with the blanket rear support and root drive.'],
  terms:[term('BOL / EOL','Beginning / end of life; ratings depend on the stated conditions.'),term('MPP','The operating point at which a photovoltaic source delivers maximum electrical power.')],
  relatedIds:flight('02.02','02.03','04.01','07.04','07.05'),sourceIds:['flight-power','flight-spectrolab','flight-rosa','flight-rosa-nasa']
 },
 '02.02':{
  summary:'The battery stores electrical energy for eclipse, peak demand and scheduled operation when solar power is insufficient. Its enclosure, cells, interconnects, sensing and battery-management electronics form one system whose usable energy depends on power, temperature, operating limits and age.',
  sections:[
   sec('purpose','Why the spacecraft needs a battery',
    p('A solar-powered spacecraft experiences a mismatch between generation and demand. In eclipse, solar generation disappears; during a maneuver or high-load task, demand may briefly exceed available power. The battery bridges that gap. Afterward the array and charging electronics must restore the withdrawn energy while supplying the loads that remain on.','flight-power'),
    p('Energy capacity and power capability answer different questions. Kilowatt-hours describe how much energy can be stored; kilowatts describe how quickly it can be delivered or replenished. A large pack can still be limited by its converter or allowed cell current. The useful energy window is smaller than nominal capacity when state-of-charge limits, aging and discharge losses are included.')),
   sec('operation','Cells, balancing and thermal control',
    p('Cells in series build voltage; parallel strings add capacity and current capability. Cell differences accumulate, so the pack needs sensing and an appropriate balancing strategy. The battery-management system monitors cell conditions and cooperates with the charge/discharge controller. Enclosure temperature is not identical to the temperature of every cell inside it.'),
    p('Saft’s space-battery documentation and VES16 datasheet provide a useful real example of the distinction between a cell, a module and a complete battery. Charge voltage, current, temperature and cycle-life statements have specific conditions. The workbench’s NMC and LFP pack options are study assumptions; VES16 evidence does not certify either selected pack.','flight-saftware','flight-ves16')),
   sec('engineering','What governs useful life',
    p('Repeated eclipse cycles make depth of discharge, temperature and time at high state of charge important design variables. A pack selected only for maximum initial energy may be a poor match for a long, frequently cycling mission. Life-test results are most useful when their temperature, charge limit and cycling profile resemble the intended operation.','flight-battery-workshop'),
    p('The enclosure must support the cells through launch, provide electrical isolation and a controlled thermal path, and leave room for harnesses, sensors and protective functions. Adding capacity also adds mass and demands more recharge energy. A mission can instead reduce eclipse computing, shift large jobs into sunlight or reserve storage energy for spacecraft services. Those choices change the required pack without changing the chemistry.'))
  ],
  suppliers:[supplier('Saft','Space lithium-ion cells, modules and batteries','A documented spacecraft-battery supplier. VES16 is a reference cell family; the workbench has not selected a Saft pack for the installed allocation.','flight-saftware','flight-ves16'),supplier('NASA Aerospace Battery Workshop','Battery test and mission experience','A learning collection rather than a hardware vendor, useful for understanding the conditions behind life claims.','flight-battery-workshop')],
  alternatives:[alternative('NMC study pack','Use the higher specific-energy option represented in the workbench.','The selected life, thermal and current assumptions must be evaluated together; mass savings alone do not establish suitability.'),alternative('LFP study pack','Compare a different cell-chemistry and pack-performance assumption.','The current preset has a different energy density and allowable rate; it should be compared at the same usable mission energy.'),alternative('Smaller pack with scheduled payload demand','Reduce computing during eclipse or other constrained periods.','This trades continuous service and completion time against storage mass and recharge demand.')],
  inspection:['The model shows pack housings and mounting interfaces. Internal cell count, vent paths and protection circuits are not established by decorative detail.'],
  terms:[term('Depth of discharge','The fraction of rated capacity withdrawn during a cycle.'),term('C-rate','Charge or discharge current expressed relative to rated capacity.'),term('BMS','Battery-management electronics and control functions.')],
  relatedIds:flight('02.01','02.03','03.02','07.05'),sourceIds:['flight-power','flight-saftware','flight-ves16','flight-battery-workshop']
 },
 '02.03':{
  summary:'Power conditioning and distribution connects changing solar and battery sources to the voltages and protected feeds that the spacecraft actually uses. It regulates energy flow, switches loads and provides the measurements needed to keep the electrical system within its limits.',
  sections:[
   sec('purpose','The electrical traffic controller',
    p('Solar arrays, batteries, accelerators, motors and avionics have different electrical needs. The power system must deliver the correct voltage, supply changing current and keep a problem on one branch from simply becoming a system-wide loss of power. Power conditioning manages the sources and conversion; distribution routes energy through selected switches, protection and harnesses.','flight-crisa'),
    p('The workbench uses independently protected MPPT source channels and a regulated main bus, with separate payload and service conversion. Its module counts and current limits are finite. If an array can generate more power than the conditioning hardware accepts, that excess cannot be treated as delivered power. Likewise, a battery energy rating does not override its bidirectional converter limit.')),
   sec('operation','MPPT, conversion and protection',
    p('Maximum-power-point tracking adjusts a solar source’s electrical operating point as conditions change. A converter then trades voltage and current while losing some input energy as heat. This is why source power, bus power and load power are different accounting points. Direct energy transfer is another source-management approach; it couples the array and bus more directly and has a different regulation trade.','flight-power','flight-crisa'),
    p('Protected load feeds combine switching, sensing and current limits. Their behavior must account for inrush at startup, normal transients and commanded load shedding. The circuit that powers essential flight functions needs an explicit relationship to the much larger customer-compute load. Control software cannot make a conductor or switch carry unlimited current safely.')),
   sec('engineering','Voltage is an architectural choice',
    p('For a fixed delivered power, raising voltage reduces current. That can reduce conductor mass and resistive loss, but it changes insulation, connectors, switching devices and electrical-clearance requirements. A voltage family should therefore be selected with the harness, source strings, battery interface and loads, not changed as an isolated label.'),
    p('The PCDU’s own losses become thermal loads. Efficiency should be evaluated at the intended load range, not only at one peak-efficiency point. Airbus Crisa’s product families illustrate real modular PCDU functions; their published power classes and bus architectures are comparison data. The study’s larger modular installation is not a certified scaling of one supplier box.','flight-crisa'))
  ],
  suppliers:[supplier('Airbus Crisa','MEGA and EVO PCDU families','Real examples of modular conditioning and protected distribution. Their documented ratings apply to their own configurations.','flight-crisa'),supplier('Moog','Integrated Avionics Unit','An example that combines command/data handling with electrical-power interfaces, useful for studying integrated versus separate boxes.','flight-iau')],
  alternatives:[alternative('MPPT source regulation','Operate array strings near their best power point as illumination and temperature change.','Additional conversion and control must be accommodated and verified.','flight-crisa'),alternative('Direct energy transfer','Use an array/battery/bus architecture with more direct source coupling.','Array matching and regulation behavior become different design constraints.','flight-crisa'),alternative('Distributed conversion near loads','Move some voltage conversion close to the computing trays.','This can reduce low-voltage routing loss while spreading heat and increasing the number of electronics modules.')],
  inspection:['Open the bus-conductor and harness pages to follow current beyond the enclosure. Shared avionics geometry may represent this allocation until a distinct PCDU enclosure is resolved.'],
  terms:[term('PCDU','Power conditioning and distribution unit.'),term('Inrush','A brief startup current that can exceed the steady operating current.'),term('Bus','A shared electrical supply and its defined voltage range.')],
  relatedIds:flight('02.01','02.02','07.05','08.01'),sourceIds:['flight-crisa','flight-power','flight-iau']
 }
};

function radiatorArticle(hardware){
 const kind=hardware?.energySystem?.thermal?.kind||'pumped';
 const local=kind==='passive-local',lift=kind==='heat-lift';
 return {
  summary:local?'This platform carries computing equipment and spreads its waste heat toward surfaces that radiate to space. Placing the heat source close to the radiator reduces the distance that heat must travel.':'Radiator panels are the spacecraft’s final heat-rejection surface. They emit infrared radiation while also absorbing some sunlight, reflected sunlight and thermal radiation from nearby objects.',
  sections:[
   sec('purpose','Where the waste heat goes',
    p('Nearly all electrical energy consumed by the data center eventually becomes heat. Vacuum removes ordinary air convection, so the spacecraft needs a continuous route from hot components to emitting surfaces. The radiator closes that route; adding a large surface is useful only if heat can actually reach it through contacts, spreaders, pipes or circulating fluid.','flight-thermal'),
    p(local?'The selected Redwire interpretation places payload computing on a local radiator platform. The source paper motivates this short path, while the workbench separately allocates bus thermal straps and their hinge accommodation. Payload electronics remain in their own equipment allocations; the platform’s mass is not a second copy of the computer.':lift?'The selected heat-lift study rejects heat at a hotter surface than the payload cooling interface. The radiator must reject both the collected payload heat and the heat pump’s electrical input. A smaller radiator is therefore exchanged for compressor power, supporting electrical hardware and a more demanding thermal machine.':'In the selected architecture, transport equipment brings heat from the core to deployable radiator banks. The panel faces, internal spreading path and coolant passages form one coupled design. A cold outer corner is not contributing the same heat rejection as a uniformly warm area.',local?'flight-redwire-thermal':lift?'flight-starcatcher':'flight-iss-thermal')),
   sec('operation','Temperature and the view to space',
    p('For an ideal surface, emitted thermal power scales with emissivity, area and the fourth power of absolute temperature. Real net rejection subtracts absorbed environmental radiation. This explains why radiator temperature, orientation and exposure matter together: an unobstructed view toward dark space and limited solar absorption can be as important as adding panel area.'),
    p('Solar absorptance and infrared emittance describe different wavelength ranges. A surface can reflect much of the Sun’s energy while emitting thermal radiation efficiently. White thermal paints and optical solar reflectors are practical examples. The coating choice also brings manufacturing, electrical-grounding, contamination and durability considerations.','flight-az93','flight-osr')),
   sec('engineering','Panel area is not the whole design',
    p('Check the full temperature chain: device junction, package, contact, collector, transport path and radiator surface. Every finite resistance needs a temperature difference to carry heat. A design that appears adequate when all components share one temperature may fail when those gradients are included. Deployment geometry also changes shadowing and the thermal view of other spacecraft surfaces.'),
    p('Radiator faces need protection during fabrication, transport and integration because contamination can alter optical behavior. Hinges, embedded passages and mechanical supports must survive launch while preserving their thermal function. The surface rendering illustrates material appearance; it does not certify optical properties, local temperatures or a provider-approved panel construction.','flight-gevs'))
  ],
  suppliers:[supplier('AZ Technology','AZ-93 thermal-control coating','A real white-coating reference; the required substrate preparation and environmental qualification are project-specific.','flight-az93'),supplier('Qioptiq / Excelitas','Optical solar reflectors','A real reflector family for comparing glass finish and optical properties. A modeled tiled surface does not select a particular tile.','flight-osr'),...(local?[supplier('Redwire','Orbital data center power/thermal concept','The published local-compute platform motivates this architecture; its concept geometry is not supplier CAD.','flight-redwire-thermal')]:[])],
  alternatives:[alternative('White paint or optical solar reflectors','Select a finish around the required solar absorption, infrared emission and integration process.','Coating application and bonded tiles have different manufacturing and electrical details.','flight-az93','flight-osr'),alternative('Hotter heat rejection','Increase radiator temperature if equipment or heat-lift hardware can support it.','Direct cooling may exceed device limits; active heat lift consumes power and increases total rejection.','flight-starcatcher')],
  inspection:['Rotate the panel to distinguish the emitting faces, thickness, root and deployment clearance. Follow the thermal-transport article to learn what carries heat to it.'],
  terms:[term('Emittance','How effectively a surface emits thermal radiation relative to an ideal emitter.'),term('View factor','The geometric share of radiation exchanged between surfaces.')],
  relatedIds:flight('01.01','03.02','03.03','07.04'),sourceIds:['flight-thermal','flight-az93','flight-osr',local?'flight-redwire-thermal':lift?'flight-starcatcher':'flight-iss-thermal','flight-gevs']
 };
}

function transportArticle(hardware){
 const kind=hardware?.energySystem?.thermal?.kind||'pumped';
 if(kind==='passive-local')return {
  summary:'The passive thermal assembly moves heat across a short path from computing devices into their radiator platform. Heat pipes and spreaders redistribute heat without a continuously driven liquid-circulation pump.',
  sections:[
   sec('purpose','A short thermal route',
    p('A concentrated device footprint cannot efficiently use an entire radiator by itself. A spreader enlarges the effective contact area, and embedded or attached heat pipes carry energy toward cooler regions. This reduces hot spots and allows more of the available surface to participate in heat rejection. Contact resistance still matters at every mechanical joint.'),
    p('The selected Redwire reference uses a local compute/radiator concept. The workbench adds a separate bus thermal route and finite battery cold control. Those additions are study accommodations: the paper’s electrical harness at the deployment hinge does not establish a qualified thermal strap across the same joint.','flight-redwire-thermal')),
   sec('operation','What happens inside a heat pipe',
    p('A sealed heat pipe contains a working fluid and a return structure such as a wick. Fluid evaporates in the warmer region and condenses in the cooler region, moving latent heat. The condensate returns so the cycle can continue. The working fluid, wall and wick must match the intended temperature range and heat load.','flight-thermal'),
    p('A passive system still has finite capacity. Capillary, boiling and other transport limits can constrain a heat pipe, while ordinary conduction limits the spreader and interfaces. Advanced Cooling Technologies’ HiK plate work is a useful real example of heat pipes embedded in a spreading assembly; it does not establish the capacity of this independently allocated platform.','flight-act')),
   sec('engineering','Heating, cooling and deployment',
    p('Keeping electronics cool during operation is only half the thermal problem. Batteries and dormant equipment may need controlled heating during cold conditions. A heater adds heat locally; insulation reduces unwanted exchange; a strap provides a conductive route. Their jobs are different, so a single large radiator cannot substitute for a complete temperature-control design.'),
    p('The deployable platform must preserve the required contact and routing geometry after launch restraint release. Flexible straps need a credible bend path and attachment design. Analysis should check both the hot operating case and the cold inactive case, including the reduced load when computing is paused. Thermal-vacuum verification provides evidence for the actual assembly and operating states.','flight-gevs'))
  ],
  suppliers:[supplier('Advanced Cooling Technologies','Heat pipes and HiK plates','A real supplier example of heat spreading and passive transport. Materials and working fluid require their own temperature-range selection.','flight-act'),supplier('Redwire','Radiator-mounted computing concept','An architectural reference for short heat paths, not a procurement declaration for each heat pipe or strap.','flight-redwire-thermal')],
  alternatives:[alternative('Direct conduction only','Use a sufficiently short, conductive path with no working fluid.','The required cross-section or temperature gradient can become large as the transport distance grows.'),alternative('Mechanically pumped loop','Move heat between separated payload and radiator locations.','Adds pumps, plumbing, fluid inventory and control interfaces.','flight-iss-thermal'),alternative('Loop heat pipe','Use a passive two-phase transport architecture for a different separation or routing need.','Startup behavior, fluid management and interfaces must be analyzed for the chosen configuration.','flight-thermal')],
  inspection:['Look for the local platform and attached bus route. There is no remote payload pump station or radiator liquid rotary crossing in this selected architecture.'],
  terms:[term('Latent heat','Energy absorbed or released during a phase change.'),term('Thermal conductance','Heat flow per degree of temperature difference across a specified path.')],
  relatedIds:flight('01.01','03.01','02.02','07.04'),sourceIds:['flight-redwire-thermal','flight-act','flight-thermal','flight-iss-thermal','flight-gevs']
 };
 if(kind==='heat-lift')return {
  summary:'A heat pump uses electrical work to move heat from a cooler collection interface to a hotter radiator. The study uses an analytical heat-lift allocation, so its apparent radiator-area benefit must be evaluated together with compressor power and all additional rejected heat.',
  sections:[
   sec('purpose','Why lift the temperature?',
    p('Computing devices have temperature limits, but hotter radiators can emit more energy per unit area. A heat pump separates those temperature choices: the payload can deliver heat at a lower temperature while the hot side rejects it at a higher temperature. This is a system trade, because the electrical power needed for the lift increases the spacecraft’s power requirement.'),
    p('Star Catcher’s published analysis discusses heat lift in the broader orbital-data-center energy problem. The selected workbench case is a self-powered analytical model. That relationship does not mean the company has supplied this spacecraft with a particular compressor, refrigerant circuit or qualified heat-pump product.','flight-starcatcher')),
   sec('operation','Follow both heat and work',
    p('The basic energy balance is hot-side rejection equals cold-side heat plus electrical work. Cooling coefficient of performance, or COP, divides the collected cold-side heat by the required work. A COP greater than one is not creation of energy: most of the rejected energy came from the payload, while the motor supplied the additional work.'),
    p('A vapor-compression implementation would include evaporation, compression, condensation and expansion. Other heat-pump technologies are possible. The working fluid, compressor, pressure levels, heat exchangers and control behavior are not established merely by assigning a COP. Their suitability depends on temperature lift, throughput, startup and the space environment.','flight-thermal')),
   sec('engineering','Count the supporting equipment',
    p('Compressor input must pass through a motor drive and power-distribution path, and the radiator must accept the resulting total hot-side load. A high COP at one condition does not guarantee the same value at another lift or part-load point. The design should expose these dependencies before comparing radiator mass savings with extra electrical and mechanical mass.'),
    p('Battery temperature control remains a separate function; it should not inherit an arbitrary hot payload-loop temperature. The live allocation does not import the ammonia inventory or pump redundancy from the conventional loop case. NASA’s ISS thermal overview is useful as a mature example of collection, transport and rejection interfaces, but its pumped loops are not evidence that this heat-lift machine exists.','flight-iss-thermal'))
  ],
  suppliers:[supplier('Star Catcher','Published orbital-data-center heat-lift analysis','A concept reference explaining the system trade. No qualified heat-pump supplier is selected in this workbench.','flight-starcatcher'),supplier('NASA / ISS program','Active Thermal Control System','A real reference architecture for thermal interfaces and heat rejection, not a heat-pump product matching this allocation.','flight-iss-thermal')],
  alternatives:[alternative('Direct pumped cooling','Reject heat without raising it above the collection temperature.','Avoids compressor work but generally requires a larger radiator at the lower allowable temperature.','flight-iss-thermal'),alternative('Local passive transport','Place computing close to a compatible radiator surface.','Reduces transport machinery but constrains packaging and temperature coupling.','flight-redwire-thermal'),alternative('Reduce or schedule compute load','Match heat generation to available rejection capacity.','Thermal relief comes at a throughput or service-availability cost.')],
  inspection:['The housing is an illustrative allocation. The model does not resolve a validated refrigerant circuit, compressor internals or a performance map.'],
  terms:[term('Cooling COP','Cold-side heat divided by the work supplied to the heat pump.'),term('Temperature lift','The difference between the colder collection and hotter rejection interfaces.')],
  relatedIds:flight('01.01','02.03','03.01','02.02'),sourceIds:['flight-starcatcher','flight-thermal','flight-iss-thermal','flight-redwire-thermal']
 };
 const independent=kind==='redundant-pumped';
 return {
  summary:'The thermal loop collects heat from equipment, moves it through liquid plumbing and delivers it to radiator panels. Pumps, headers, accumulators, valves and cold-control equipment make the heat path function as an integrated system.',
  sections:[
   sec('purpose','Connect equipment to the radiator',
    p('Cold plates collect heat over relatively small areas. A circulating fluid carries that heat to a larger rejection surface, allowing computing and radiator locations to be chosen somewhat independently. The loop’s useful capacity depends on flow, fluid properties, allowable temperature rise and pressure loss, as well as the radiator’s ability to reject the delivered energy.'),
    p(independent?'This architecture allocates two separately contained, half-duty loops. Independent fluid circuits reduce shared containment paths, but two half-duty loops do not automatically provide full computing capacity after losing one. The remaining available capacity and allowable load must be assessed explicitly.':'This architecture uses duty/standby pumping with shared distribution paths. A spare pump can cover a pump failure without creating a second independent coolant circuit. Headers, fluid inventory and radiator sections may remain common paths, which is why pump count alone is not a complete description of redundancy.')),
   sec('operation','Pumps, fluid volume and branches',
    p('The pump provides a pressure rise to overcome hydraulic losses; it does not create the temperature difference required at the cold plate. Parallel branches need a sensible flow distribution. An accumulator accommodates changes in fluid volume and establishes part of the pressure behavior as temperature and operating conditions change.','flight-iss-thermal'),
    p('The workbench allocates pressurized ammonia for this transport case. Fluid selection affects the operating pressure, freezing margin, materials and component designs. NASA’s ISS system is a valuable real ammonia-loop example, but its pumps, seals and operational evidence cannot simply be transferred to a newly scaled data-center loop.','flight-iss-thermal')),
   sec('engineering','Treat the entire route as hardware',
    p('Hoses or articulated connections crossing a deployment joint must retain their pressure boundary through assembly, stowage and motion. More folding sections introduce additional interfaces even when radiator area is unchanged. A routing model should include line length, bend clearance, fittings, isolation points and the locations where sensors can reveal actual operating conditions.'),
    p('Cold-control heaters serve components that would otherwise become too cold. They add power consumption and local heat, rather than improving the main radiator’s rejection limit. Evaluate startup, shutdown and reduced-load cases as well as full compute operation. Thermal-vacuum and pressure-system verification need the selected fluid circuit and realistic control states.','flight-thermal','flight-gevs'))
  ],
  suppliers:[supplier('NASA / ISS program','External Active Thermal Control System','A documented operating architecture with pumps, accumulators, ammonia and radiators. It is a system example, not the installed bill of materials.','flight-iss-thermal'),supplier('Advanced Cooling Technologies','Passive heat pipes and HiK plates','A real supplier comparison for applications where shorter transport paths can remove the need for mechanical circulation.','flight-act')],
  alternatives:[alternative('Independent liquid circuits','Split heat sources and radiators into separately contained systems.','Reduces shared fluid paths but duplicates hardware and needs explicit capacity allocation.'),alternative('Passive local heat transport','Place sources near heat pipes and radiator surfaces.','Avoids continuous pumping while constraining geometry and transport limits.','flight-act','flight-redwire-thermal'),alternative('Heat lift','Reject at a higher temperature using added electrical work.','The hot side must reject both payload heat and compressor input.','flight-starcatcher')],
  inspection:['Follow the collection path, distribution line and radiator root. The displayed tubing is a conceptual route; fittings and internal passage details are not a released plumbing drawing.'],
  terms:[term('Accumulator','A volume-control element that accommodates fluid expansion and pressure behavior.'),term('Pressure drop','The pressure lost as fluid moves through a resistance.')],
  relatedIds:flight('01.01','03.01','02.02','07.04'),sourceIds:['flight-iss-thermal','flight-thermal','flight-act','flight-gevs','flight-redwire-thermal','flight-starcatcher']
 };
}

Object.assign(articles,{
 '03.03':{
  summary:'Multilayer insulation, or MLI, reduces unwanted radiative heat exchange across covered spacecraft surfaces. It helps preserve the intended thermal routes, so equipment can send heat toward its radiator instead of exchanging it indiscriminately with the surroundings.',
  sections:[
   sec('purpose','Control where heat can travel',
    p('An enclosure wall sees sunlight, Earth radiation and other spacecraft surfaces as its orientation changes. A tailored blanket reduces that exchange and moderates temperature swings. It is especially useful around hardware that needs to stay warm while nearby radiators remain exposed. Insulating an intended radiator face would work against that radiator’s purpose.','flight-thermal'),
    p('A blanket is not simply a colored sheet. It combines thin reflective layers with spacing and attachment details chosen for the environment and geometry. Beyond Gravity’s satellite-insulation documentation shows that blanket assemblies are tailored products, with openings, seams and specialized outer materials rather than one universal stack.','flight-mli')),
   sec('operation','Why many thin layers help',
    p('Reflective layers reduce radiant exchange across the blanket, while low-conductance spacing limits heat leaking through contacts between them. Compression, seams and attachment points can create more conductive paths. The installed behavior therefore depends on how the blanket is fitted, not only the nominal number of layers.','flight-thermal'),
    p('Outer surfaces face a different environment from internal layers. They may need electrical grounding, resistance to handling or environmental exposure, and compatibility with nearby optics and radiators. Venting also matters during ascent because gas trapped between layers must escape without damaging the blanket or nearby equipment. These are design and integration details, not decorative choices.')),
   sec('engineering','Tailor the blanket around real interfaces',
    p('Cutouts must accommodate antennas, sensors, thruster clearances, fluid ports, connectors and moving mechanisms. An oversized gap can create a thermal leak; an intrusive blanket edge can block a field of view or snag a joint. Removable covers need a repeatable installation so inspections and late access do not silently change the thermal configuration.'),
    p('MLI does not automatically solve internal overheating. Equipment still needs a controlled route to a sink, and electrical heaters may still be necessary during cold conditions. Thermal analysis and vacuum testing should use the actual blanket seams, coverage and operating states that matter to the temperature budget, rather than treating every covered wall as perfectly insulated.','flight-gevs'))
  ],
  suppliers:[supplier('Beyond Gravity','Satellite insulation assemblies','A real supplier of tailored spacecraft blankets; the illustrated study cover does not specify a released layer schedule or attachment drawing.','flight-mli'),supplier('NASA','Thermal-control technology survey','A practical reference for comparing blankets with coatings, heaters and conductive thermal paths.','flight-thermal')],
  alternatives:[alternative('Surface coating','Control absorption and emission directly on an exposed wall.','Useful when radiative exchange is desired; it does not provide the same decoupling as a blanket.','flight-az93'),alternative('Thermal straps and controlled heaters','Deliberately route heat or add it where needed.','These solve local conduction or cold-temperature problems and still need appropriate external insulation.'),alternative('Different blanket coverage','Leave selected surfaces exposed and insulate others.','Improves routing flexibility but requires analysis of seams, openings and changing view factors.')],
  inspection:['Compare covered walls with exposed radiator faces. Metallic-looking folds indicate blanket appearance; the render does not resolve individual reflective layers or predict blanket performance.'],
  terms:[term('MLI','Multilayer insulation: a tailored assembly of reflective layers and separators.'),term('Thermal leak','An unintended heat-transfer path through a gap, attachment or conductive bridge.')],
  relatedIds:flight('03.01','03.02','07.02','04.03'),sourceIds:['flight-mli','flight-thermal','flight-gevs','flight-az93']
 },
 '04.01':{
  summary:'Control moment gyroscopes turn the spacecraft by redirecting angular momentum stored in spinning wheels. A cluster can provide substantial pointing torque without consuming propellant for every maneuver, while its geometry and stored momentum constrain what it can do.',
  sections:[
   sec('purpose','Turn the spacecraft while preserving momentum',
    p('The data center must orient arrays, radiators, antennas and engines in useful directions. A CMG applies an internal torque: the spacecraft turns as the gyro’s momentum direction changes. External disturbances still add momentum to the combined system, so the cluster also needs a way to unload accumulated momentum through an external interaction.','flight-gnc'),
    p('A reaction wheel mainly changes spin speed. A CMG mainly changes the direction of an already spinning rotor using a gimbal. This distinction explains why CMGs can provide useful maneuver torque, and why their controls must consider gimbal angles as well as the amount of stored angular momentum.','flight-cmg')),
   sec('operation','The cluster is more than four independent motors',
    p('Each gimbal produces torque in a direction set by its current geometry. The controller combines the units to produce the requested spacecraft torque. At certain configurations, the cluster can lose authority in a needed direction; steering logic manages these singular configurations and the available momentum envelope.','flight-cmg-design'),
    p('Momentum capacity and torque rating are different quantities. Momentum describes how much rotational state the cluster can accommodate; torque describes how quickly it can change the spacecraft’s angular momentum. A faster slew may require more torque, while long disturbance exposure can consume momentum capacity even when the spacecraft hardly changes its pointing.')),
   sec('engineering','Pointing performance includes flexible hardware',
    p('The controller works with estimated attitude and rates from the sensor suite. Array and radiator flexibility, gimbal friction, rotor disturbance and structural modes can affect the achieved pointing. Increasing a nominal actuator rating does not automatically produce a quieter optical-terminal line of sight. Mechanism and spacecraft control designs must be evaluated together.'),
    p('Airbus’s CMG 15-45 S documentation provides a real wheel-and-gimbal example with distinct torque and momentum specifications. The selected workbench cluster uses a reference mechanism for preliminary sizing. Its arrangement, structural mounting, control law and mission-specific performance still require their own evidence.','flight-cmg'))
  ],
  suppliers:[supplier('Airbus Defence and Space','CMG 15-45 S','A documented CMG reference used to explain rotor, gimbal and rating boundaries. Datasheet performance is not a verified spacecraft pointing result.','flight-cmg'),supplier('NewSpace Systems','Reaction wheels','A real alternative momentum-exchange actuator family for comparing torque, stored momentum and control complexity.','flight-wheel')],
  alternatives:[alternative('Reaction-wheel cluster','Use wheel-speed changes for attitude torque.','Often simpler kinematics, with a different torque-to-mass and momentum trade.','flight-wheel'),alternative('Thruster control','Exchange momentum through expelled propellant.','Requires propellant and introduces impulse, plume and minimum-command considerations.','flight-propulsion'),alternative('Magnetic unloading','Use Earth’s magnetic field to remove accumulated momentum.','Available torque changes around the orbit and cannot point arbitrarily at every instant.','flight-gnc')],
  inspection:['Use the gyro-motion animation to distinguish rotor spin from gimbal motion. Examine the cluster arrangement; a moving render is not a simulation of a singularity-avoidance control law.'],
  terms:[term('Angular momentum','The rotational quantity exchanged between the spacecraft and its internal actuators.'),term('Singularity','A mechanism configuration in which a requested torque direction becomes unavailable or poorly conditioned.')],
  relatedIds:flight('04.02','04.03','07.01','08.01'),sourceIds:['flight-cmg','flight-cmg-design','flight-gnc','flight-wheel','flight-propulsion']
 },
 '04.02':{
  summary:'Magnetorquer rods create a commanded magnetic dipole that interacts with Earth’s magnetic field. Their principal role here is to remove accumulated momentum from the gyro-controlled spacecraft without expending propellant.',
  sections:[
   sec('purpose','Give internal actuators somewhere to unload',
    p('Gyros and reaction wheels exchange momentum with the spacecraft but cannot erase momentum delivered by external disturbances. Solar pressure, aerodynamic forces and other torques can gradually push a cluster toward its usable limit. Magnetic unloading provides an external torque so the spacecraft can bring stored momentum back into a more useful range.','flight-gnc'),
    p('A torquer rod typically combines a wound coil with a magnetic core. The drive electronics control coil current, producing the commanded dipole. NewSpace Systems publishes real rods in different magnetic-moment classes; those examples are useful for understanding what is purchased beyond a simple visible cylinder.','flight-rod')),
   sec('operation','The orbit changes available torque',
    p('Magnetic torque is the cross product of the commanded dipole and the local magnetic field. The instantaneous torque is therefore perpendicular to the field. Three orthogonal rods provide control over the dipole direction, but they do not remove that physical restriction. A requested torque along the field cannot be produced at that instant.'),
    p('The field direction and strength change along an orbit. An unloading controller uses those changes over time, coordinating magnetic torque with the momentum-exchange actuators. A favorable average capability does not mean the same torque is continuously available. This makes orbit, pointing demands and unload scheduling part of the hardware sizing problem.','flight-gnc')),
   sec('engineering','Accommodation includes magnetic cleanliness',
    p('Rod placement affects wiring, heat dissipation and magnetic interference. Nearby magnetometers should not confuse a commanded actuator field with the ambient field used for estimation. Motors, ferromagnetic structure and current loops can also contribute unwanted magnetic signatures. Sensor placement and operating sequences need a coherent system design.'),
    p('Magnetic moment, current, voltage, duty cycle and temperature limits must be treated together. A large nominal dipole does not establish continuous unloading performance at the selected orbit. The study’s mass relation is an allocation, while supplier curves and environmental verification apply to a specific rod and driver configuration.','flight-rod','flight-gevs'))
  ],
  suppliers:[supplier('NewSpace Systems','Magnetorquer rods','A real manufacturer with selectable rod capability. No catalog rod is selected simply by displaying the allocated dipole.','flight-rod'),supplier('Airbus Defence and Space','CMG 15-45 S','The complementary internal momentum actuator; magnetic rods support its long-term momentum management rather than replacing all of its pointing functions.','flight-cmg')],
  alternatives:[alternative('Thruster unloading','Remove momentum with carefully arranged impulses.','Works independently of geomagnetic torque direction but spends propellant and requires plume accommodation.','flight-propulsion'),alternative('Larger momentum storage','Increase the interval before unloading is needed.','Adds actuator capability but does not remove persistent external torque.'),alternative('Disturbance-conscious attitude planning','Choose allowable orientations that reduce accumulated torque.','Must be balanced against power, thermal, communication and payload pointing needs.')],
  inspection:['Locate the three-axis rod allocation and compare it with the gyro cluster. Rods have no moving gimbals; their operation is electrical and magnetic rather than visibly mechanical.'],
  terms:[term('Magnetic dipole moment','The strength and direction of the magnetic actuator, commonly expressed in ampere-square-metres.'),term('Momentum unloading','Using an external torque to restore useful capacity in internal momentum actuators.')],
  relatedIds:flight('04.01','04.03','02.03','08.01'),sourceIds:['flight-rod','flight-gnc','flight-cmg','flight-gevs','flight-propulsion']
 },
 '04.03':{
  summary:'The attitude sensor suite tells the controller which way the spacecraft is pointing and how fast it is rotating. Star trackers, rate sensors and complementary observations support an estimate that remains useful across different illumination and operating conditions.',
  sections:[
   sec('purpose','Measure orientation before commanding it',
    p('Attitude knowledge and attitude control are different. A powerful actuator cannot point accurately if the controller has a biased or stale estimate of orientation. Optical communications, radiator placement and solar tracking all depend on knowing the relationship between spacecraft axes and the external reference frame.','flight-gnc'),
    p('A star tracker images a star field and matches it against a catalog to infer orientation. A rate sensor measures rotation over short intervals. Sun sensors and magnetometers can provide complementary information for coarse acquisition or other operating states. The selected suite is an allocated combination, not evidence that every sensor type is individually resolved in the render.','flight-gnc')),
   sec('operation','Combine measurements with a model',
    p('An attitude estimator propagates orientation using measured rates and corrects that estimate with external observations. Sensor noise, alignment error, timing and bias affect the result. A slowly changing gyro bias can cause drift between absolute observations, while a bad time tag can make an otherwise accurate measurement inconsistent with the current state.'),
    p('Tracker heads need a clear field of view and protection against bright objects and stray light. Their baffles help control illumination; they are not arbitrary decorative cones. Sodern’s HYDRA range illustrates multiple optical-head and processing configurations, including accommodation choices that help maintain useful observations through changing geometry.','flight-hydra')),
   sec('engineering','Alignment belongs to the whole spacecraft',
    p('Sensor mounting must preserve the relationship between the measured frame and the equipment being pointed. Thermal distortion, structural flexibility and assembly tolerances can change this relationship. An optical terminal may add its own fine-pointing loop, so bus-attitude knowledge and terminal line-of-sight error should be budgeted separately.'),
    p('Software needs to recognize invalid or unavailable observations and manage operating modes. A nominal accuracy number does not describe performance during initial acquisition, bright-object exclusion or recovery from a restart. End-to-end verification should exercise the sensor interfaces, estimator and actuators together with the timing and alignment assumptions used by the design.','flight-avionics','flight-gevs'))
  ],
  suppliers:[supplier('Sodern','HYDRA star-tracker range','A real optical attitude-sensor family. Field-of-view and processing configurations belong to the selected supplier variant, not the generic model.','flight-hydra'),supplier('NASA','Guidance, navigation and control technology survey','A useful reference for comparing star trackers, Sun sensors, gyros and magnetic measurements.','flight-gnc')],
  alternatives:[alternative('Star tracker plus rate sensor','Combine accurate external updates with fast short-term rotation measurements.','Needs good timing, alignment and behavior when stars are temporarily unavailable.','flight-gnc'),alternative('Coarse Sun and magnetic sensing','Support lower-accuracy acquisition or protective modes.','Does not substitute for every precision optical-pointing requirement.','flight-gnc'),alternative('Terminal-level fine pointing','Correct small optical line-of-sight errors locally.','Adds terminal hardware and controls while still requiring the bus to acquire the target.','flight-click')],
  inspection:['Look at the optical apertures and baffle directions, then compare them with nearby arrays and antennas. Rendered visibility is illustrative rather than a full stray-light or exclusion-angle analysis.'],
  terms:[term('Attitude','The orientation of the spacecraft relative to a reference frame.'),term('Boresight','The reference viewing direction of an optical sensor or antenna.')],
  relatedIds:flight('04.01','04.02','05.03','08.01'),sourceIds:['flight-hydra','flight-gnc','flight-avionics','flight-gevs','flight-click']
 },
 '05.01':{
  summary:'The S-band package supports tracking, telemetry and command: the communication needed to monitor and operate the spacecraft. Its antenna coverage and radio functions serve a different purpose from the much higher-rate customer-data links.',
  sections:[
   sec('purpose','Keep the spacecraft operable',
    p('Telemetry reports health and state, commands request authorized changes, and tracking observations help determine motion. These functions remain important when customer computing is idle or a high-rate terminal is unavailable. Their bandwidth needs may be modest compared with payload data, but their availability and relationship to flight avionics are central to operations.','flight-comms'),
    p('A patch antenna is one component of the complete chain. Transceiver electronics, amplification, filtering, switching, cables and the ground station also determine whether a command or telemetry link works. The workbench groups these functions in one allocation; seeing two patches does not establish that two complete independent radios are installed.')),
   sec('operation','Coverage is an antenna property',
    p('Broad-beam antennas trade high gain for coverage over more directions. Opposing mounting locations can improve access as the body orientation changes, but structure, deployment geometry and polarization still affect the link. An antenna radiation pattern is a directional measurement, not simply the outline of the patch in the 3D view.'),
    p('Anywaves’ S-band TT&C antenna is a real reference with a specified frequency range, polarization and beam behavior. It is useful for understanding antenna accommodation. Those characteristics should be carried into a link analysis with transmitter power, receiver sensitivity, propagation loss and ground-antenna capability before claiming coverage.','flight-anywaves')),
   sec('engineering','Separate a radio link from an operations service',
    p('A visible ground pass only creates an opportunity. The spacecraft and station must share compatible frequencies, waveforms, coding, command interfaces and operating arrangements. Available airtime and contact scheduling determine how much telemetry can return and how promptly a command can be delivered.'),
    p('Flight avionics should manage which commands can affect power, pointing or propulsion and how those commands are checked and acknowledged. Essential communication also needs a power and thermal path compatible with intended spacecraft states. A high-rate optical link does not automatically provide a backup command path unless that function has been explicitly designed.','flight-avionics'))
  ],
  suppliers:[supplier('Anywaves','S-band TT&C antenna','A real antenna reference. It is not a complete radio, ground-network contract or assurance of all-attitude coverage.','flight-anywaves'),supplier('Moog','Integrated Avionics Unit','A reference for the onboard command/data-handling interfaces that connect spacecraft communication to flight functions.','flight-iau')],
  alternatives:[alternative('Broad-beam RF command link','Prioritize operational coverage with comparatively simple pointing.','Available gain and data rate are limited relative to a narrow high-gain antenna.','flight-comms'),alternative('Separate high-gain payload link','Send bulk customer data through Ka-band or optical terminals.','Adds acquisition, pointing and ground-network requirements.','flight-nisar','flight-tbird'),alternative('Relay-assisted operations','Use a compatible relay service to extend access.','Requires terminal and protocol compatibility plus an actual service arrangement; geometric visibility alone is insufficient.')],
  inspection:['Inspect the patch locations on opposite sides and look for potential obstruction by deployables. Antenna colors and shapes do not encode a measured radiation pattern.'],
  terms:[term('TT&C','Tracking, telemetry and command.'),term('Link budget','An accounting of signal power, losses, noise and required margin along a communication path.'),term('Polarization','The orientation behavior of the radio wave’s electric field.')],
  relatedIds:flight('05.02','05.03','07.05','08.01'),sourceIds:['flight-anywaves','flight-comms','flight-avionics','flight-iau','flight-nisar','flight-tbird']
 },
 '05.02':{
  summary:'The Ka-band terminal sends data through a narrow, high-gain radio beam formed by a reflector antenna. Its pointing mechanism, radio-frequency electronics and ground receiver must work together to turn nominal transmitter capacity into useful delivered data.',
  sections:[
   sec('purpose','Concentrate radio energy toward the receiver',
    p('A reflector gathers energy from a feed and forms a directional beam. Greater gain can improve a long-distance link, but the narrower beam demands more accurate pointing. The gimbal allows the antenna direction to change without requiring every spacecraft surface to follow the same motion.','flight-comms'),
    p('The full RF chain includes modulation, coding, frequency conversion, amplification, filters and feed losses. A reflector diameter alone does not determine data rate. The receiving ground antenna, noise temperature, atmospheric conditions and allowable frequency use belong in the same link analysis.')),
   sec('operation','Track a moving line of sight',
    p('As the spacecraft passes a station, the required antenna direction changes continuously. Commanded pointing uses navigation and attitude information, while the positioner must respect travel limits, structural blockage and cable routing. A narrow beam creates an explicit error budget for bus knowledge, gimbal positioning, alignment and structural motion.'),
    p('NASA JPL’s NISAR high-rate downlink paper is a useful concrete example because it discusses the radio and the ground system together, including coding and polarization. Its demonstrated design choices are mission-specific. They do not imply that the workbench’s generic dish has the same performance or interfaces.','flight-nisar')),
   sec('engineering','Rate, contact time and weather',
    p('A high instantaneous rate is only part of daily capacity. Contact duration, usable elevation angles, outages, protocol overhead and scheduling reduce the amount of application data delivered. Storage buffers data between contacts; the payload fabric must also move that data to the terminal fast enough when a contact begins.'),
    p('Ka-band links require attention to atmospheric attenuation, including weather on the ground path. Site diversity, adaptive operations and buffering can improve service continuity, but they have infrastructure and scheduling costs. The study’s Ka allocation is a payload-downlink package; it does not automatically add an independently qualified command-and-telemetry fallback.','flight-comms'))
  ],
  suppliers:[supplier('NASA JPL','NISAR Ka-band high-rate downlink','A documented mission architecture and technical paper. This is a reference implementation, not a selected commercial terminal for the study.','flight-nisar'),supplier('Anywaves','S-band TT&C antenna','A useful comparison illustrating why broad-coverage spacecraft operations and narrow high-rate downlink often use different hardware.','flight-anywaves')],
  alternatives:[alternative('Optical downlink','Use a much shorter wavelength and a narrow optical beam.','Requires fine pointing and an appropriate ground-weather strategy.','flight-tbird'),alternative('Lower-frequency RF link','Choose a different balance of antenna size, spectrum and propagation behavior.','Available bandwidth, hardware dimensions and ground compatibility change.','flight-comms'),alternative('Several ground sites','Increase usable opportunities and diversify local conditions.','Adds service contracts, routing and coordination rather than increasing the spacecraft’s instantaneous transmitter rating.')],
  inspection:['Use terminal pointing to inspect the reflector, feed direction and gimbal travel. The animation does not establish a continuous, obstruction-free ground contact.'],
  terms:[term('Antenna gain','How strongly an antenna concentrates energy in a direction relative to a reference.'),term('Coding','Structured redundancy used to recover data in a noisy link.')],
  relatedIds:flight('01.03','01.04','04.03','05.01','05.03'),sourceIds:['flight-nisar','flight-comms','flight-anywaves','flight-tbird']
 },
 '05.03':{
  summary:'An optical terminal sends information on a laser beam aimed through a telescope. The narrow beam supports high data rates, but useful service also depends on acquisition, precise tracking, receiver compatibility and the availability of the destination.',
  sections:[
   sec('purpose','Connect the computing spacecraft to a destination',
    p('A terminal can be intended for a ground downlink or an intersatellite crosslink. Those are different link geometries and operating environments. Installing several telescopes provides potential interfaces, but terminal count alone does not prove simultaneous service, protocol compatibility or access to a commercial relay network.','flight-comms'),
    p('MIT Lincoln Laboratory’s TBIRD mission demonstrated high-rate optical downlink using a body-pointed architecture. TESAT’s SCOT80 is a real optical crosslink-terminal example. They are valuable references precisely because their functions and accommodation differ; neither should be silently substituted for the workbench’s generic articulated terminal.','flight-tbird','flight-tesat')),
   sec('operation','Acquire first, then hold the beam',
    p('The terminal must find the other endpoint, establish a usable optical signal and keep its beam aligned as relative geometry changes. Coarse pointing brings the target into the acquisition region. Fine steering corrects smaller and faster errors. Navigation, time, spacecraft attitude, structural stability and optical alignment contribute to the total line-of-sight problem.'),
    p('NASA’s CLICK technology description illustrates the role of fine-steering mirrors in optical links. That mechanism is not the same as rotating an entire spacecraft or telescope. Some missions, including TBIRD, deliberately use different pointing arrangements. The relevant architecture should be stated before comparing pointing performance or mechanism mass.','flight-click','flight-tbird')),
   sec('engineering','A fast link still needs a data service',
    p('The terminal consumes data from storage and the payload fabric. Buffering, packetization and retransmission behavior determine how the application handles interruptions and imperfect delivery. Peak optical line rate is not identical to customer throughput, especially when contact time, overhead or another shared link constrains the route.'),
    p('Clouds can interrupt optical ground paths. Ground-site diversity and store-and-forward scheduling can help, while crosslinks move the problem into a network with its own capacity and access constraints. Telescope thermal stability, contamination control and stray-light behavior also need attention. A rendered beam or successful line-of-sight calculation establishes geometry, not a contracted communication service.','flight-comms'))
  ],
  suppliers:[supplier('TESAT','SCOT80 optical communication terminal','A real terminal family and documented demonstration program. Its interface standard and capability are not automatically selected for this spacecraft.','flight-tesat'),supplier('MIT Lincoln Laboratory','TBIRD','A demonstrated optical downlink with body pointing and data-management lessons; its pointing architecture differs from the displayed gimbaled study terminal.','flight-tbird')],
  alternatives:[alternative('Body pointing','Aim a compatible terminal by orienting the spacecraft itself.','Can reduce terminal mechanism complexity while coupling communications to array and radiator attitude.','flight-tbird'),alternative('Gimbal plus fine steering','Separate coarse terminal motion from fast optical correction.','Adds mechanisms, alignment and control interfaces.','flight-click'),alternative('RF downlink','Use a radio terminal for a different availability and ground-network trade.','Antenna, spectrum and achievable-rate constraints differ.','flight-nisar')],
  inspection:['Rotate around the aperture and use terminal pointing to examine line-of-sight clearance. The optical prescription and fine-steering internals are not resolved supplier optics.'],
  terms:[term('Acquisition','Establishing the initial usable optical connection.'),term('Crosslink','A communication path between spacecraft.'),term('Goodput','Useful application data delivered after protocol overhead and losses.')],
  relatedIds:flight('01.03','01.04','04.03','05.02','08.01'),sourceIds:['flight-tbird','flight-tesat','flight-click','flight-comms','flight-nisar']
 }
});

function engineArticle(hardware){
 const aero=hardware?.input?.engine==='aero';
 return {
  summary:'The engine heads convert stored propellant energy into thrust for orbital maneuvers. Fuel and oxidizer arrive through separate pressure-fed paths, meet in the injector and burn in the chamber before the hot gas expands through the nozzle.',
  sections:[
   sec('purpose','Change orbital motion',
    p('The engine changes spacecraft velocity by expelling mass. Its thrust direction must be related to the spacecraft attitude and maneuver plan; the spacecraft’s default viewing direction has no effect on the physical thrust vector. Propellant reserved for later maneuvering or disposal remains onboard until an actual burn consumes it.'),
    p(aero?'The selected study package uses Aerozine-50 and nitrogen tetroxide. NASA’s Apollo service-propulsion history documents this propellant pairing in Aerojet’s AJ10-137. The historical engine was much larger than these study heads; chemistry heritage does not validate the workbench’s adapted engine mass or geometry.':'The selected study package uses MMH fuel and MON-3 oxidizer. ArianeGroup’s S400 family is a real pressure-fed bipropellant reference. Its published thrust, mixture, pressure and propellant envelope applies to that engine; an entered study operating point outside the envelope is not a newly qualified S400 variant.',aero?'flight-apollo':'flight-engine')),
   sec('operation','Pressure, valves and nozzle expansion',
    p('Helium pressurization pushes the liquids through feed lines and valves to the injector. The selected propellants are hypergolic, meaning that contact initiates combustion under their intended conditions. Valve actuation uses electrical energy, while the thrust energy comes principally from the chemical propellants rather than the spacecraft electrical bus.','flight-engine','flight-apollo'),
    p('Thrust and specific impulse answer different questions. Thrust sets the instantaneous force and, together with mass, the acceleration. Specific impulse describes propellant use per delivered impulse. Nozzle geometry, chamber conditions and mixture affect performance. A pair of engines also needs an explicit mounting and command arrangement; count alone does not guarantee a particular failure response.')),
   sec('engineering','The engine affects nearby hardware',
    p('Plume direction and hot surfaces constrain placement of blankets, antennas, radiators and other sensitive equipment. Mechanical mounts transfer thrust into the primary structure. Feed interfaces must deliver compatible propellants at the required conditions, and electrical interfaces must support the intended valve sequence and telemetry.'),
    p('Maneuver duration, repeated starts, thermal behavior and delivered impulse need verification for the actual engine and mission. NASA’s propulsion survey is useful for comparing propulsion classes, while a manufacturer’s engine drawing and qualification evidence address a particular product. A mass-scaling relation is preliminary sizing rather than a substitute for either.','flight-propulsion'))
  ],
  suppliers:[supplier('ArianeGroup','S400 bipropellant apogee motors','A real MMH/NTO-family engine reference. The workbench scales preliminary head mass; it does not reproduce a supplier’s qualified design.','flight-engine'),supplier('Aerojet / NASA Apollo program','AJ10-137 service-propulsion engine','Historical Aerozine-50/NTO hardware used to teach chemistry and pressure-feed heritage, not the selected small engine product.','flight-apollo')],
  alternatives:[alternative('Electric propulsion','Trade high propellant efficiency for low thrust and electrical demand.','Maneuvers take longer and compete with the data center for electrical power.','flight-propulsion'),alternative('Monopropellant propulsion','Use a different feed and reaction architecture.','Performance, catalyst, storage and qualification requirements change.','flight-propulsion'),alternative('Different storable bipropellant engine','Match an actual product to the required thrust and lifetime.','Tank, feed, mixture and mounting choices must follow the selected engine envelope.','flight-engine')],
  inspection:['Follow each nozzle axis toward its mounting structure. The model does not resolve injector passages or demonstrate plume clearance and thrust alignment.'],
  terms:[term('Specific impulse','Delivered impulse divided by propellant weight flow; commonly expressed in seconds.'),term('Hypergolic','A fuel/oxidizer pair that ignites on contact under its intended operating conditions.')],
  relatedIds:flight('06.02','06.03','06.04','06.06','06.07','07.01'),sourceIds:[aero?'flight-apollo':'flight-engine','flight-engine','flight-apollo','flight-propulsion','flight-feed']
 };
}

Object.assign(articles,{
 '06.02':{
  summary:'The pressurization and feed assembly delivers fuel and oxidizer to the engines at usable conditions while keeping the fluids separated. It connects the helium bottle, liquid tanks, valves, regulators, sensors and engine interfaces into one propulsion system.',
  sections:[
   sec('purpose','Turn stored fluids into a controlled supply',
    p('The liquid tanks store enough propellant for the mission, but the engine needs a specific flow and inlet-pressure range during each burn. A pressure-fed system uses stored gas energy to push the liquids toward the engines. This avoids a turbopump at the cost of pressurant hardware and liquid vessels designed for the required pressure.','flight-sp8112'),
    p('Fuel and oxidizer remain in separate liquid circuits until the engine injector. Isolation, check, service and thruster valves have different jobs: a component intended to prevent reverse flow is not automatically a substitute for a commanded shutoff. Moog’s propulsion-component catalog illustrates these distinct component classes.','flight-feed')),
   sec('operation','Regulation is a system behavior',
    p('A regulator reduces bottle pressure to a controlled downstream range as gas is supplied to the tanks. The remaining pressurant pressure, gas temperature and regulator behavior affect the ability to maintain that range. NASA SP-8112 explains pressurization as a coupled design problem rather than a fixed pressure value attached to a bottle.','flight-sp8112'),
    p('Liquid pressure falls through lines, fittings, valves and injector restrictions. The engine inlet condition is therefore different from the pressure measured in the tank. During valve opening and closing, transient pressure and flow can differ from steady conditions. A credible feed design connects these operating states to the engine’s allowable envelope.')),
   sec('engineering','Interfaces need chemical and mechanical evidence',
    p('Every wetted surface, seal and joint must be compatible with its fluid and service duration. The fuel and oxidizer sides may look similar in a rendering, but that does not authorize interchange of components. NESC’s material-compatibility work shows why actual alloy condition, fluid quality and geometry matter beyond a broad material-family label.','flight-fluid-compatibility'),
    p('Line supports, inspection access, fill/drain connections and sensor placement affect assembly and operations. A pressure schematic and a geometric layout answer different questions and must agree. The workbench’s allocated assembly mass does not establish valve redundancy, verified leak performance, pressure-transient response or an approved servicing procedure.'))
  ],
  suppliers:[supplier('Moog','Spacecraft propulsion components','A real source of valves, regulators and related feed components. Individual functions and compatible configurations must be selected explicitly.','flight-feed'),supplier('ArianeGroup','S400 engine interfaces','A real downstream engine reference that helps explain why the feed system must meet a particular inlet envelope.','flight-engine')],
  alternatives:[alternative('Regulated pressure feed','Maintain a bounded supply pressure through most of the usable pressurant range.','Adds a regulator and requires analysis of its behavior and end-of-life margin.','flight-sp8112'),alternative('Blowdown pressure feed','Allow tank pressure to decline as propellant is consumed.','Simplifies some hardware but changes thrust and flow conditions through the mission.','flight-sp8112'),alternative('Pump-fed architecture','Use a pump to establish required feed pressure.','Changes power, machinery and control requirements; it is not represented by this pressure-fed allocation.','flight-propulsion')],
  inspection:['Follow the conceptual bottle-to-tank and tank-to-engine routes. Valve symbols or housings illustrate allocation; the view is not a released piping schematic.'],
  terms:[term('Ullage','The gas-filled space above the liquid inventory in a tank.'),term('Regulator','A component that controls downstream pressure within its design envelope.'),term('Wetted surface','A surface exposed to the stored or flowing fluid.')],
  relatedIds:flight('06.01','06.03','06.04','06.05','06.08'),sourceIds:['flight-sp8112','flight-feed','flight-engine','flight-fluid-compatibility','flight-propulsion']
 },
 '06.03':{
  summary:'The fuel vessel stores the liquid fuel while its propellant-management device helps deliver liquid to the outlet in low gravity. Its shell, internal acquisition hardware and mounts are dry hardware; the loaded fuel is a separate consumable inventory.',
  sections:[
   sec('purpose','Store fuel and deliver the usable portion',
    p('A tank volume must accommodate liquid, ullage and the intended operating conditions. The engine’s oxidizer-to-fuel ratio sets the fuel share of the total propellant load, but density converts that mass into a different volume. Two visually similar fuel and oxidizer vessels need not have equal capacity or equal loaded mass.'),
    p('On the ground, gravity keeps liquid near a low outlet. In orbit, surface forces and vehicle accelerations can place it elsewhere. A propellant-management device, or PMD, uses internal features such as vanes or screened channels to acquire liquid while restricting gas ingestion. NASA’s historical review is a useful guide to the different approaches.','flight-pmd-history')),
   sec('operation','The outlet must stay connected to liquid',
    p('A PMD is a fluid-management structure rather than a pump. Its behavior depends on fluid wetting, surface tension, acceleration and the required flow. The available liquid may form shapes that a simple filled-sphere graphic cannot represent. Acquisition near depletion is especially important because nominal loaded fuel is not identical to fully usable fuel.'),
    p('Helium enters the pressurization space as fuel leaves, providing the driving pressure for the feed system. Gas temperature, dissolved gas and transient demands can affect system behavior. The vessel, acquisition device and regulator should therefore be evaluated together rather than treating the tank as an isolated geometric container.','flight-sp8112')),
   sec('engineering','Separate chemical, pressure and mount requirements',
    p('The selected fuel chemistry determines the wetted-material requirements. A tank suitable for one hydrazine-family fuel is not automatically approved for every blend, impurity level or service duration. NESC’s MMH/MON-3 work is a useful example of why material condition and exposure evidence matter for thin pressure boundaries.','flight-fluid-compatibility'),
    p('The mounts transfer launch loads from a filled vessel into the spacecraft without creating unacceptable local shell stresses. They must also accommodate thermal expansion and preserve line connections. Northrop Grumman’s PMD-tank catalog shows actual mission-specific vessels; its examples do not validate an arbitrary scaled sphere with an allocated dry mass.','flight-pmd'))
  ],
  suppliers:[supplier('Northrop Grumman','PMD propellant tanks','A real supplier catalog with mission-specific vessels and acquisition hardware. The study tank is not a selected catalog model.','flight-pmd'),supplier('Moog','Propulsion feed components','Relevant upstream/downstream interfaces for tank isolation and delivery; compatible valve selection remains distinct from vessel selection.','flight-feed')],
  alternatives:[alternative('Screen-channel or vane PMD','Use capillary structures to acquire liquid in the intended acceleration environment.','The design must match flow, fluid and depletion conditions.','flight-pmd-history'),alternative('Positive-expulsion tank','Separate pressurant and liquid using a bladder or diaphragm.','Changes material compatibility, usable volume and mechanical behavior.','flight-pmd-history'),alternative('Settling-assisted delivery','Use a mission operation that places liquid favorably before demand.','Requires an appropriate acceleration source and operational sequence rather than relying solely on passive acquisition.')],
  inspection:['Inspect shell shape, bosses and mounting supports. Open the fuel-inventory page for the liquid allocation; the internal PMD is not fully resolved in this external model.'],
  terms:[term('PMD','Propellant-management device: internal hardware that helps acquire liquid in low gravity.'),term('Residual','Propellant remaining but unavailable or reserved outside the modeled usable delivery.')],
  relatedIds:flight('06.02','06.04','06.05','06.06','07.01'),sourceIds:['flight-pmd','flight-pmd-history','flight-sp8112','flight-fluid-compatibility','flight-feed']
 },
 '06.04':{
  summary:'The oxidizer vessel stores the liquid that reacts with the fuel in the engine. Its pressure boundary and acquisition hardware must deliver the required oxidizer flow while preserving chemical compatibility and keeping the oxidizer circuit separate from the fuel circuit.',
  sections:[
   sec('purpose','Accommodate the mixture requirement',
    p('Engine mixture ratio specifies oxidizer mass flow divided by fuel mass flow. The oxidizer load is therefore not necessarily half the combined liquid mass. Its density, allowable fill condition and remaining ullage determine the required internal volume. Changing engine chemistry or mixture assumptions can alter both vessel accommodation and the mass distribution of the spacecraft.'),
    p('The oxidizer tank has its own liquid outlet and pressurant connection. Propellant-management hardware helps keep liquid available at the outlet when gravity does not collect it at the bottom. Northrop Grumman’s actual PMD vessels and NASA’s acquisition-device review illustrate why internal details are specific to the intended mission and fluid.','flight-pmd','flight-pmd-history')),
   sec('operation','Maintain liquid delivery without mixing circuits',
    p('During a burn, helium pressure drives oxidizer through its feed path while the fuel moves through a separate path. Both need suitable inlet conditions at the engine. A stable tank pressure alone does not prove that the correct oxidizer flow reaches the injector; line losses, valves and acquisition behavior are part of that result.','flight-sp8112'),
    p('The oxidizer grade is a controlled material specification. MON-3 is a mixed-oxide-of-nitrogen grade; NTO and other MON grades have distinct specification identities. The selected engine package determines which chemistry appears in the live inventory. A label such as “nitrogen oxides” is not enough for procurement or compatibility decisions.','flight-mon-spec')),
   sec('engineering','A similar shape does not imply an interchangeable tank',
    p('Oxidizer-contacting alloys, welds, seals and cleanliness conditions need appropriate evidence. An external shell material name does not describe every wetted joint or thin internal feature. NASA’s NESC bulletin examines the dependence of compatibility evidence on material form, fluid water content and exposure, which is directly relevant to evaluating such assumptions.','flight-fluid-compatibility'),
    p('Mounting design must account for the filled tank’s loads and its changing contribution as propellant is consumed. Inspection access, service fittings and isolation should fit the assembly sequence. The study allocates tank mass and geometry; it does not reproduce a provider’s pressure-vessel drawing, internal screen design or qualified oxidizer servicing hardware.'))
  ],
  suppliers:[supplier('Northrop Grumman','PMD propellant tanks','A real source of mission-specific tank designs. Published examples help frame questions about capacity, pressure and acquisition rather than selecting a scaled catalog item.','flight-pmd'),supplier('Moog','Oxidizer-path valves and regulators within its propulsion portfolio','A real component supplier reference; compatibility and the exact selected configuration need product-level confirmation.','flight-feed')],
  alternatives:[alternative('Different oxidizer grade','Use the grade required by a selected, compatible engine system.','Requires coordinated engine, materials, thermal and procurement review.','flight-mon-spec','flight-engine'),alternative('Positive-expulsion architecture','Separate gas and oxidizer with a moving barrier.','The barrier introduces its own compatibility, life and volume constraints.','flight-pmd-history'),alternative('Separate smaller vessels','Distribute oxidizer storage across the structure.','Can improve packaging while adding plumbing, mounts and fluid-management interfaces.')],
  inspection:['Compare the oxidizer vessel’s volume and mounts with the fuel vessel. The internal liquid state and PMD wetting behavior are not visualized by the solid shell.'],
  terms:[term('Mixture ratio','Oxidizer mass flow divided by fuel mass flow.'),term('MON','Mixed oxides of nitrogen; a family of controlled oxidizer grades.')],
  relatedIds:flight('06.02','06.03','06.05','06.07','07.01'),sourceIds:['flight-pmd','flight-pmd-history','flight-sp8112','flight-mon-spec','flight-fluid-compatibility','flight-feed']
 },
 '06.05':{
  summary:'The helium bottle stores high-pressure gas that supplies the propulsion pressurization system. It is a pressure vessel with its own shell, liner or overwrap, bosses and mounts; the helium charge inside it is counted separately.',
  sections:[
   sec('purpose','Store pressurization energy compactly',
    p('The liquid tanks need pressure to deliver propellant, but storing all the pressurant at liquid-tank pressure would require a large volume. A separate high-pressure bottle holds gas compactly, and a regulator reduces its pressure for downstream use. The bottle must retain sufficient usable gas and pressure through the planned maneuver sequence.','flight-sp8112'),
    p('Northrop Grumman’s pressurant-vessel portfolio includes metal and composite-overwrapped designs. A metal vessel carries pressure in its shell. A composite-overwrapped vessel combines a liner and load-carrying fiber construction with particular boss and interface designs. The exterior carbon-like appearance alone does not identify a qualified layup or liner.','flight-pressurant-tank')),
   sec('operation','Pressure changes as gas is used',
    p('Bottle pressure depends on gas mass, volume and temperature. As helium is withdrawn, its state changes; the thermal response of the gas and vessel can affect the pressure available to the regulator. High-pressure behavior may require a real-gas model rather than a single ideal-gas relation.'),
    p('A useful inventory calculation includes the gas that remains when the bottle can no longer support the required downstream conditions. That remainder has mass even if it is no longer useful for the planned feed pressure. Bottle volume, initial charge, regulator requirements and gas temperature should therefore be selected together.','flight-sp8112')),
   sec('engineering','A vessel is qualified for a defined life',
    p('Pressure-vessel assessment includes maximum operating pressure, proof and burst evidence, temperature, pressure cycles and credible damage. NASA’s COPV guidance emphasizes damage tolerance and life demonstration. Fiber direction, liner behavior, manufacturing details and inspection history cannot be recovered from a mesh or a mass allocation.','flight-copv-life'),
    p('Mounts must hold the bottle through launch without imposing unsuitable local loads or damaging a composite surface. Bosses support valves and lines while transmitting their loads into the vessel. Ground servicing and the flight installation must preserve access and identification of the correct connections. These interfaces can govern a practical design even when the estimated gas volume looks small.'))
  ],
  suppliers:[supplier('Northrop Grumman','Pressurant tanks','A real pressure-vessel supplier with metal and composite-overwrapped products. Selection requires the actual pressure, temperature, gas and life envelope.','flight-pressurant-tank'),supplier('Moog','Pressurization components','A real component family for the regulator and isolation interfaces connected to the bottle.','flight-feed')],
  alternatives:[alternative('All-metal pressure vessel','Use a metallic shell to carry pressure.','Changes mass, manufacturing, damage response and inspection compared with a composite-overwrapped design.','flight-pressurant-tank'),alternative('Composite-overwrapped vessel','Use fiber reinforcement around a liner.','Can offer useful mass performance but requires configuration-specific life and damage evidence.','flight-copv-life'),alternative('Different storage pressure or bottle count','Trade compactness against vessel and regulation requirements.','Changing pressure can affect dry mass, usable residual, fittings and ground servicing.')],
  inspection:['Inspect the bottle bosses and mounts, then open the helium-inventory article. The external finish illustrates construction intent; individual fiber layers and liner stresses are not modeled.'],
  terms:[term('COPV','Composite-overwrapped pressure vessel.'),term('Proof pressure','A specified verification pressure used in a controlled qualification or acceptance program.'),term('Usable pressurant','Gas that can still be delivered at conditions meeting downstream requirements.')],
  relatedIds:flight('06.02','06.03','06.04','06.08','07.01'),sourceIds:['flight-pressurant-tank','flight-sp8112','flight-copv-life','flight-feed']
 },
 '06.08':{
  summary:'The helium charge is the consumable gas that pressurizes the liquid-propellant system. It supplies pressure rather than chemical combustion energy, and its mass is separate from the bottle and the liquid fuel and oxidizer.',
  sections:[
   sec('purpose','Push the liquids without joining the combustion pair',
    p('The pressure-fed system needs gas to replace liquid volume as fuel and oxidizer leave their tanks. Helium’s chemical inertness makes it useful for this role. It travels through the pressurization plumbing and establishes the force that drives liquid toward the engines; it is not a third liquid propellant mixed into the injector by the design.','flight-sp8112'),
    p('Gas procurement is a real supply-chain decision. NASA has documented aerospace helium supply from Messer, Linde and Airgas, while DLA lists helium within its aerospace-energy responsibilities. Those examples establish actual suppliers and procurement organizations, not a selected source or purity specification for this workbench.','flight-helium-supply','flight-dla')),
   sec('operation','Loaded gas is different from usable gas',
    p('At loading, helium occupies both the high-pressure bottle and the gas space in the liquid tanks. More gas passes through regulation as propellant is consumed. Required inventory depends on displaced liquid volume, target pressure, gas temperatures and remaining bottle pressure. Some helium remains in the bottle when downstream conditions can no longer be maintained.'),
    p('Temperature changes affect both stored pressure and delivered pressurization. The gas can exchange heat with bottle walls, lines and liquid-tank contents. A single initial pressure is therefore not a full mission model. NASA SP-8112 provides a detailed route into pressurant sizing, component selection and the coupled thermal behavior.','flight-sp8112')),
   sec('engineering','Keep the mass accounting and specification clear',
    p('This MEL entry is the gas inventory at loading. The pressure bottle is a separate dry-hardware allocation, and helium added to tank ullage remains part of the spacecraft mass until a modeled vent or other loss removes it. Simply consuming fuel does not mean the same fraction of helium instantly disappears from the vehicle.'),
    p('Purity, allowable contamination, leak performance and delivery conditions must match the actual propulsion design. A commercial gas name is not a complete aerospace procurement specification. Ground equipment also needs a compatible pressure and cleanliness boundary, but this page describes the flight inventory rather than a loading procedure or a reusable ground gas panel.'))
  ],
  suppliers:[supplier('Messer, Linde and Airgas','Helium supply to NASA centers','Actual aerospace-gas suppliers documented by NASA. Contract evidence does not identify a selected flight batch, purity or workbench supplier.','flight-helium-supply'),supplier('Defense Logistics Agency Energy','Aerospace Energy procurement','A procurement and logistics reference, not a helium manufacturer or a hardware selection.','flight-dla')],
  alternatives:[alternative('Different bottle pressure and volume','Trade initial storage conditions while maintaining the required usable inventory.','Bottle mass, regulator margin and gas thermal behavior change together.','flight-sp8112'),alternative('Another compatible pressurant','Consider a different gas only in a redesigned, verified system.','Molecular mass, solubility, chemical compatibility and thermal behavior can change requirements.','flight-sp8112'),alternative('Blowdown architecture','Let propellant-tank pressure decline through the operating interval.','Changes the required pressure history and engine performance instead of simply deleting gas mass.','flight-sp8112')],
  inspection:['This entry has no independent solid model. Open the related helium bottle and feed assembly to see the hardware that contains and uses the charge.'],
  terms:[term('Pressurant','A gas used to establish or maintain pressure in a fluid system.'),term('Charge','The quantity of gas loaded into the system.'),term('Gas residual','Inventory that remains when required delivery conditions can no longer be met.')],
  relatedIds:flight('06.02','06.05','06.06','06.07'),sourceIds:['flight-sp8112','flight-helium-supply','flight-dla','flight-pressurant-tank']
 }
});

function fuelArticle(hardware){
 const aero=hardware?.input?.engine==='aero';
 const fuel=aero?'Aerozine-50':'MMH';
 return {
  summary:fuel+' is the liquid fuel inventory loaded for the selected pressure-fed propulsion package. This page covers the consumable material and its role in the maneuver budget; the vessel, valves and engine are separate hardware allocations.',
  sections:[
   sec('purpose','What the fuel contributes',
    p(aero?'Aerozine-50 is approximately an equal-mass blend of hydrazine and unsymmetrical dimethylhydrazine. The selected pairing is nitrogen tetroxide oxidizer. NASA’s Apollo documentation provides a historical system example, including separate fuel and oxidizer storage and helium-driven delivery. The workbench’s small engine adaptation is not an Apollo engine.':'MMH stands for monomethylhydrazine. The selected engine package pairs it with MON-3 oxidizer, with separate storage and feed paths until the injector. ArianeGroup’s S400 documentation is a real example of this storable bipropellant family. The fuel inventory is chemical energy carried for later maneuvers.',aero?'flight-apollo-manual':'flight-engine'),
    p('A maneuver budget first determines the required combined propellant mass under the chosen propulsion assumptions. The engine’s oxidizer-to-fuel ratio then divides that load between the two liquids. Fuel density converts mass to tank volume. Changing chemistry affects more than the label: the engine, volumes, material compatibility and thermal accommodation all need to stay consistent.')),
   sec('operation','Loaded, reserved and consumed are different states',
    p('At loading, the inventory includes liquid intended for planned maneuvers and quantities held for reserves or modeled residuals. During a burn, the fuel flow follows the engine’s required mixture relationship. A reserve is still real onboard mass; it is not additional impulse that has already been delivered.'),
    p('Not all fuel inside a tank is necessarily usable at the engine. Acquisition limits, line inventory and pressure conditions can leave residual material. The PMD and feed-system pages explain the hardware that makes delivery possible. Mission analysis should keep this distinction visible when comparing wet mass, dry mass and remaining maneuver capability.','flight-pmd-history','flight-sp8112')),
   sec('engineering','Chemistry is a controlled specification',
    p(aero?'The Apollo manuals document the blend and its historical use, but a modern procurement decision needs a current applicable specification, supplier acceptance and system compatibility evidence. The study has not selected an Aerozine-50 manufacturer or approved production batch. That open selection should not be filled by assigning the MMH supplier to a different fuel.':'DLA’s MIL-PRF-27404 record defines the controlled MMH propellant specification. Mitsubishi Gas Chemical NEXT is an actual MMH producer, but a commercial product listing is not proof that its listed grade meets the mission’s procurement specification. Supplier capability and accepted propellant grade are separate questions.',aero?'flight-apollo-manual':'flight-mmh-spec',...(aero?[]:['flight-mmh-maker'])),
    p('Fluid condition and wetted materials affect long-duration storage. NASA’s NESC compatibility work for MMH/MON-3 illustrates why alloy condition, water content and exposure duration deserve evidence. These liquids require specialized facilities and procedures; the site’s inventory model supports design learning, not instructions for handling or loading propellant.','flight-fluid-compatibility'))
  ],
  suppliers:aero?[supplier('Aerojet / NASA Apollo program','Historical Aerozine-50/NTO system','A documented propulsion reference. No present-day fuel manufacturer is assigned by this historical example.','flight-apollo'),supplier('Defense Logistics Agency Energy','Aerospace propellant procurement','A reference for controlled aerospace supply chains, not the manufacturer of the modeled liquid.','flight-dla')]:[supplier('Mitsubishi Gas Chemical NEXT','Monomethylhydrazine','A verified chemical producer listing. Propellant-grade acceptance, impurities and the actual delivery specification remain open.','flight-mmh-maker'),supplier('Defense Logistics Agency','MIL-PRF-27404 and Aerospace Energy','Specification and procurement references; DLA is not the installed fuel manufacturer.','flight-mmh-spec','flight-dla')],
  alternatives:[alternative(aero?'MMH / MON-3':'Aerozine-50 / NTO','Choose a complete compatible engine-and-propellant package.','Performance, density and material requirements change together; fuel alone is not a drop-in replacement.',aero?'flight-engine':'flight-apollo'),alternative('Electric propulsion','Spend electrical energy to achieve a different propellant-efficiency trade.','Longer burn durations and electrical demand can change mission operations.','flight-propulsion')],
  inspection:['The liquid inventory has no separate solid geometry. Open the fuel vessel to inspect the container, mounts and conceptual feed connection.'],
  terms:[term('Wet mass','Spacecraft mass including its loaded consumables.'),term('Propellant reserve','Inventory retained for uncertainty or later required maneuvers rather than already spent.')],
  relatedIds:flight('06.01','06.02','06.03','06.07','06.08'),sourceIds:[aero?'flight-apollo-manual':'flight-mmh-spec',aero?'flight-apollo':'flight-mmh-maker','flight-engine','flight-dla','flight-pmd-history','flight-fluid-compatibility','flight-sp8112','flight-propulsion']
 };
}

function oxidizerArticle(hardware){
 const aero=hardware?.input?.engine==='aero';
 const oxidizer=aero?'NTO':'MON-3';
 return {
  summary:oxidizer+' supplies the oxidizing component of the selected bipropellant package. Its loaded mass is accounted independently from fuel, helium and the dry vessel, so the propulsion budget can track mixture, storage volume and remaining consumables coherently.',
  sections:[
   sec('purpose','Bring the oxidizer to the reaction',
    p('A rocket carries the materials needed for its chemical reaction rather than depending on atmospheric oxygen. Oxidizer therefore contributes a substantial share of the onboard propellant mass. The engine’s mixture ratio determines that share, and its density converts the mass into the required liquid storage volume.'),
    p(aero?'The selected study uses nitrogen tetroxide with Aerozine-50. NASA’s Apollo service-propulsion history documents this pairing and its hypergolic operation. That history establishes a real reference system, not qualification of the workbench’s smaller engine adaptation.':'The selected study uses MON-3 with MMH fuel. MON-3 is a controlled mixed-oxide-of-nitrogen grade, with nominally three percent nitric oxide in the nitrogen-tetroxide mixture. The grade designation matters; it is more specific than the generic chemical name shown in many introductory propulsion descriptions.',aero?'flight-apollo':'flight-mon-spec')),
   sec('operation','Match the two liquid streams',
    p('Fuel and oxidizer travel through separate tanks, valves and lines. At the injector, the intended mass-flow ratio supports the engine’s specified operating point. An adequate total propellant mass does not guarantee a complete maneuver if one side runs out of usable liquid before the other.'),
    p('Storage conditions and acquisition affect how much of the load can be delivered. Pressurant maintains the driving pressure, while the PMD helps acquire liquid in low gravity. Residuals in the tank or feed path remain part of mass accounting even when they are unavailable for useful thrust. These relationships are covered in NASA’s acquisition and pressurization references.','flight-pmd-history','flight-sp8112')),
   sec('engineering','Use the actual grade and compatible materials',
    p('MIL-PRF-26539 is the official specification family for nitrogen-tetroxide and MON propellants. It provides a more precise procurement starting point than a supplier’s general chemical name. CF Industries’ company filing identifies actual dinitrogen-tetroxide production at Yazoo City; it does not identify a selected flight lot or establish the exact grade used here.','flight-mon-spec','flight-cf-nto'),
    p('Oxidizer compatibility concerns the complete wetted circuit, including thin features, welds, seals and contamination condition. NESC’s MMH/MON-3 bulletin is a useful example of quantitative compatibility work. It should inform questions about evidence, not be read as universal approval of every metal, geometry or service duration represented by the model.','flight-fluid-compatibility'))
  ],
  suppliers:[supplier('CF Industries','Dinitrogen-tetroxide production at Yazoo City','A manufacturer’s primary filing establishes a real production source. The study does not select a purchased grade, lot or delivery contract.','flight-cf-nto'),supplier('Defense Logistics Agency','MIL-PRF-26539 and Aerospace Energy','Official specification and procurement references; not a claim that DLA manufactures the oxidizer.','flight-mon-spec','flight-dla')],
  alternatives:[alternative(aero?'MMH / MON-3 package':'Aerozine-50 / NTO package','Change to a compatible propulsion architecture with its own documented operating envelope.','Requires coordinated fuel, engine, tank and materials changes.',aero?'flight-engine':'flight-apollo'),alternative('Other specified MON grade','Use only the grade accepted by the selected propulsion hardware.','Temperature behavior, impurity limits and qualification evidence must match that choice.','flight-mon-spec'),alternative('Non-bipropellant propulsion','Select an electric or monopropellant system for a different mission trade.','Changes electrical demand, thrust, performance and stored-material requirements.','flight-propulsion')],
  inspection:['This inventory is contained within the oxidizer vessel. Open that hardware page for the shell, mounts and conceptual delivery route.'],
  terms:[term('Oxidizer','The reactant that provides the oxidizing component of combustion.'),term('NTO','Common abbreviation for nitrogen tetroxide, also written N2O4.'),term('Propellant grade','A specified composition and quality boundary for procured material.')],
  relatedIds:flight('06.01','06.02','06.04','06.06','06.08'),sourceIds:['flight-mon-spec','flight-cf-nto','flight-dla','flight-pmd-history','flight-sp8112','flight-fluid-compatibility',aero?'flight-apollo':'flight-engine','flight-propulsion']
 };
}

export function flightKnowledge(record,catalog,hardware){
 if(record?.category!=='flight'||record.massAccounting!=='mel-allocation')return null;
 const article=record.wbs==='03.01'?radiatorArticle(hardware):record.wbs==='03.02'?transportArticle(hardware):record.wbs==='06.01'?engineArticle(hardware):record.wbs==='06.06'?fuelArticle(hardware):record.wbs==='06.07'?oxidizerArticle(hardware):record.wbs==='07.04'?mechanismArticle(hardware):record.wbs==='09.01'?adapterArticle(hardware):articles[record.wbs];
 if(!article)return null;
 const sourceIds=[...new Set([...(article.sourceIds||[]),...article.sections.flatMap(s=>s.paragraphs.flatMap(p=>p.sources||[])),...(article.suppliers||[]).flatMap(s=>s.sources||[]),...(article.alternatives||[]).flatMap(a=>a.sources||[])])];
 return {...article,key:'flight-'+record.wbs,sourceIds};
}

Object.assign(articles,{
 '07.01':{
  summary:'The primary frame provides the main mechanical route from installed equipment to the launch interface. It holds trays, tanks and actuators in their required locations while maintaining enough stiffness for launch survival, alignment and controlled on-orbit motion.',
  sections:[
   sec('purpose','Give every load a route',
    p('An equipment item experiences launch acceleration and vibration through its attachments. Those forces must travel through trays, brackets and frame members to the spacecraft-to-launcher interface. Looking for that continuous load path is more informative than judging strength from a member’s visual thickness. The retained spacecraft-side launch fitting belongs to this structural boundary.'),
    p('Primary structure differs from an enclosure panel or a local equipment cover because it carries the main spacecraft loads. Beyond Gravity’s structure portfolio illustrates real central structures, struts and panels. NASA’s structures survey explains the broader material and mechanism choices without implying that a generic frame is already qualified.','flight-beyond-structure','flight-structure')),
   sec('operation','Stiffness and strength solve different problems',
    p('Strength limits relate to yielding, fracture, buckling and other failures. Stiffness determines deformation and modal response. A frame can be strong enough to avoid breaking but too flexible to preserve sensor alignment or meet a launcher’s coupled-load requirements. Joint flexibility and local attachments often matter as much as long uninterrupted members.'),
    p('Mass is distributed rather than concentrated at one point. Filled tanks, computing trays and deployed structures change center of mass, inertia and dynamic behavior. The stowed launch configuration and deployed operational configuration therefore need different structural questions, even though they share many of the same components.')),
   sec('engineering','Design the joints and assembly sequence',
    p('Fastener access, connector clearance and the ability to install or remove a tray affect the layout. Joints must transfer load while accommodating tolerances and thermal expansion. Dissimilar materials can introduce additional interface considerations. A complete frame design includes fittings, inserts, local reinforcements and inspection access, not only long beams.'),
    p('Verification combines analysis with an appropriate environmental test program. NASA’s GEVS provides a useful verification framework, while a launcher user guide gives actual mission-interface environments and processes. The selected launcher’s requirements govern its integration; the Falcon guide is an example rather than a universal specification for every vehicle in this site.','flight-gevs','flight-falcon-guide'))
  ],
  suppliers:[supplier('Beyond Gravity','Satellite central structures, struts and panels','A real structural-system supplier. The workbench frame is a preliminary geometry and mass allocation, not a released Beyond Gravity design.','flight-beyond-structure'),supplier('SpaceX','Falcon payload interface requirements','A launch-provider reference showing how structural accommodation connects to a real launch service. It is not the manufacturer of this modeled frame.','flight-falcon-guide')],
  alternatives:[alternative('Frame with separate enclosure panels','Concentrate primary loads in members and fittings.','Can simplify access but adds joints and may use panel area less efficiently.'),alternative('Load-bearing sandwich enclosure','Let structural walls participate in the main load path.','Changes panel attachments, cutout reinforcement and the consequences of late access changes.','flight-structure'),alternative('Composite central structure','Tailor stiffness and thermal behavior using a composite load path.','Requires laminate, joint, manufacturing and inspection evidence specific to that construction.','flight-beyond-structure')],
  inspection:['Trace a tray or tank attachment back to the launch interface. Compare frame members with enclosure walls, which have a separate MEL allocation.'],
  terms:[term('Load path','The connected route by which force passes through hardware and joints.'),term('Mode shape','A characteristic deformation pattern during vibration.'),term('Buckling','Loss of structural stability under a compressive load.')],
  relatedIds:flight('01.02','06.03','06.04','07.02','09.01'),sourceIds:['flight-beyond-structure','flight-structure','flight-gevs','flight-falcon-guide']
 },
 '07.02':{
  summary:'Sandwich walls use thin, comparatively stiff face sheets separated by a light core to provide useful bending stiffness without a solid plate’s mass. They enclose the core and support the interfaces assigned to each wall.',
  sections:[
   sec('purpose','Separate material to resist bending',
    p('When a panel bends, its opposite faces experience tension and compression. Spacing those faces apart gives them greater mechanical leverage, while the core keeps their separation and transfers shear. This makes sandwich construction attractive when broad surfaces need stiffness at limited mass. It does not eliminate the need for local reinforcement.','flight-structure'),
    p('A real panel is a stack of selected face material, adhesive and core, with edges and attachments designed as part of the assembly. Hexcel’s HexWeb range illustrates core choices; Beyond Gravity offers completed satellite panels with metallic or composite faces. A core datasheet and a finished-panel specification answer different questions.','flight-hexweb','flight-beyond-structure')),
   sec('operation','Loads must enter the sandwich correctly',
    p('A bolt cannot simply clamp a fragile low-density core as if it were a solid metal block. Inserts, edge members or other reinforced regions transfer concentrated loads into the faces and core. Cutouts for connectors or equipment interrupt the load path and may need local changes in thickness, density or reinforcement.'),
    p('Bond quality connects the faces to the core. Local disbonding can reduce stiffness or create a new failure mode even when the external surface looks intact. Venting, moisture control, thermal expansion and the chosen manufacturing process affect how the completed panel behaves in its intended environment.')),
   sec('engineering','A wall can have several jobs',
    p('An enclosure wall may also conduct heat, provide an electrical reference surface, support a blanket or carry local equipment. These functions do not automatically follow from its structural stiffness. A thermally isolating core can be useful in one location and inconvenient in another, so heat paths and electrical connections need explicit interfaces.'),
    p('The workbench counts the actual wall areas after occupied cutouts and keeps internal shielding in a separate allocation. These boundaries prevent double-counting, but they do not define a released laminate or bondline. Inspection and environmental verification must address the manufactured panel and attachments, rather than only the nominal face material.','flight-gevs'))
  ],
  suppliers:[supplier('Beyond Gravity','Satellite honeycomb panels','A real supplier of mission-specific panels with aluminum or carbon-fiber-reinforced faces. No specific layup is selected by this rendering.','flight-beyond-structure'),supplier('Hexcel','HexWeb honeycomb','A real core-material family with different materials, cell geometries and densities; not a complete panel or flight acceptance record.','flight-hexweb')],
  alternatives:[alternative('Metal face sheets','Use a familiar conductive material for panel faces.','Thermal expansion, mass and local joint behavior must meet the mission requirements.','flight-beyond-structure'),alternative('Composite face sheets','Tailor directional stiffness and thermal response.','Requires laminate design, process control and appropriate joint/inspection methods.','flight-beyond-structure'),alternative('Machined or stiffened solid panel','Avoid a bonded lightweight core in a local region.','May simplify some attachments while increasing mass for the same broad-area bending stiffness.')],
  inspection:['Inspect edges and openings to understand the wall envelope. The rendered face does not expose individual adhesive layers, cell-wall thickness or every local insert.'],
  terms:[term('Face sheet','An outer structural layer of a sandwich panel.'),term('Core shear','The shear loading carried by the lightweight material between the faces.'),term('Insert','A reinforced feature that transfers a concentrated attachment load into a panel.')],
  relatedIds:flight('03.03','07.01','07.03','07.05'),sourceIds:['flight-structure','flight-hexweb','flight-beyond-structure','flight-gevs']
 },
 '07.03':{
  summary:'Internal shielding is an allocated material barrier intended to reduce radiation exposure at selected electronics. Its effectiveness depends on the orbit, particle environment, material, geometry and device response, so shielding mass alone cannot establish computing lifetime.',
  sections:[
   sec('purpose','Reduce exposure where it matters',
    p('Radiation can gradually change device behavior or cause individual disruptive events. NASA’s radiation-hardness-assurance guidance distinguishes total ionizing dose, displacement damage and single-event effects. These mechanisms need different evidence and mitigations. A generic statement that a box is “radiation shielded” does not answer all three questions.','flight-rha'),
    p('Shielding modifies the particle environment at the equipment. Existing structure and neighboring hardware also contribute material along some directions. The relevant geometry is therefore the path from the environment to a sensitive device, including gaps and openings, rather than simply the average kilograms of shielding divided by the outside area.')),
   sec('operation','Material changes the transported radiation',
    p('Particles lose energy and can generate secondary radiation as they pass through material. The result depends on particle type, energy and the sequence of materials. Adding thickness can be useful, but a universal conversion from metal thickness to years of reliable service is not available without the environment and device response.'),
    p('Juno’s electronics vault is a concrete mission example: its titanium enclosure was part of an architecture designed for Jupiter’s intense radiation environment. It demonstrates the value of concentrating sensitive electronics behind a deliberate barrier. Its material, mission and protection result are not a ready-made prescription for this Earth-orbiting data center.','flight-juno')),
   sec('engineering','Combine transport analysis with electronics evidence',
    p('Radiation assurance starts with the mission environment and actual part susceptibility. Shielding analysis should then estimate conditions at the devices, while testing and available part data address response. Error correction, redundancy, watchdogs and recovery software can mitigate some consequences but do not automatically prevent destructive effects.','flight-rha','flight-avionics'),
    p('A local shield also affects thermal conduction, mass properties, mounting and access to connectors. The enclosure must still reject computing heat. The workbench treats shielding as a separate mass allocation and does not resolve a complete internal shield mesh or a particle-transport calculation. The parts page is therefore a place to learn the design questions, not infer a verified radiation lifetime.'))
  ],
  suppliers:[supplier('NASA JPL','Juno electronics vault','A documented mission design for a much different radiation environment; useful as an architectural example, not a selected shielding product.','flight-juno'),supplier('BAE Systems','RAD750 flight-computer family','A real radiation-hardened electronics alternative that illustrates how device selection complements shielding rather than merely adding enclosure mass.','flight-rad750')],
  alternatives:[alternative('Local shielding around sensitive electronics','Place material where the protected hardware needs it.','Can reduce unnecessary mass but requires detailed treatment of openings and heat paths.'),alternative('Radiation-tolerant device selection','Choose parts with evidence appropriate to the mission environment.','Performance, availability and cost may differ from high-throughput terrestrial accelerators.','flight-rad750','flight-rha'),alternative('System-level error management','Use detection, correction, checkpointing and controlled recovery.','Addresses particular failure consequences; it does not establish immunity to every radiation mechanism.','flight-avionics')],
  inspection:['This allocation has no separately resolved internal shield model. Use surrounding structure for context and follow the accelerator and avionics pages for the protected functions.'],
  terms:[term('TID','Total ionizing dose: cumulative deposited ionizing energy affecting device behavior.'),term('Single-event effect','A device response initiated by an individual energetic-particle interaction.'),term('Radiation assurance','The process of matching environment, device evidence and mitigations to mission requirements.')],
  relatedIds:flight('01.01','01.03','07.02','08.01'),sourceIds:['flight-rha','flight-juno','flight-avionics','flight-rad750','flight-structure']
 },
 '07.05':{
  summary:'The harness carries electrical power, commands, timing and data between equipment. Its conductors, insulation, shields, connectors, supports and routing are an engineered subsystem whose losses and interfaces can constrain the entire spacecraft.',
  sections:[
   sec('purpose','Make the equipment interfaces real',
    p('A power budget does not deliver energy until a physical circuit connects source and load. Current flows through both supply and return paths, creating resistance losses and voltage drop. Signal links have different needs, including controlled impedance, shielding, pair geometry or optical handling. They should not be sized by the same rule as high-current power feeds.'),
    p('Glenair’s interconnect portfolio includes power, coaxial, controlled-impedance and optical assemblies. These are useful examples of distinct harness constructions. A connector family or cable type must still be selected against the actual equipment interface, environment and assembly needs, rather than chosen only for its visual appearance.','flight-harness')),
   sec('operation','Current, heat and voltage drop interact',
    p('For a given transmitted power, lower voltage requires more current. Conductor resistance then causes both voltage drop and heating, proportional to current and current squared respectively. Length and cross-section therefore influence whether the load receives its required voltage and whether the harness remains within its thermal capability.'),
    p('High-speed links are transmission paths, not ideal wires. Connector transitions, cable length, bend geometry and termination affect signal quality. The payload fabric and flight command network may use different protocols and electrical layers; each interface needs its own channel budget and compatibility evidence.','flight-spacewire','flight-quantum')),
   sec('engineering','Routing is part of the specification',
    p('Harness supports provide strain relief and keep cables away from sharp edges, hot surfaces and moving joints. Deployment crossings need a repeatable bend path and sufficient motion allowance. Service loops and connector access help assembly, but unused slack can interfere with mechanisms if not deliberately restrained.'),
    p('NASA-STD-8739.4 is a useful source for cable and harness workmanship, including terminations, identification and inspection. It should be applied through the project’s actual requirements. The study’s copper and attachment mass allowances do not specify every connector, gauge, shield termination or acceptance test. Some architecture families allocate harness mass without separate rendered cable geometry.','flight-workmanship'))
  ],
  suppliers:[supplier('Glenair','Integrated cable and flex assemblies','A real supplier for multiple interconnect technologies. The modeled routes do not select a released cable assembly or connector pinout.','flight-harness'),supplier('Airbus Crisa','Power conditioning and distribution units','A real source-side interface example showing why protected feeds and harness capability must be considered together.','flight-crisa')],
  alternatives:[alternative('Higher-voltage distribution with local conversion','Reduce current over long power routes.','Adds conversion and insulation requirements near the loads while changing conductor sizing.'),alternative('Optical data interconnect','Move selected data over fiber.','Changes transceiver power, bend limits, connectors and handling; it does not carry spacecraft electrical power.','flight-harness'),alternative('Rigid-flex or integrated backplane','Consolidate connections inside a local electronics assembly.','Can reduce free wiring while coupling mechanical design and maintenance to the electronics layout.')],
  inspection:['Where separate geometry is available, follow both supply and return routing and look at mechanism crossings. The view does not resolve all pins, shields, insulation layers or connector retention features.'],
  terms:[term('Voltage drop','The reduction in voltage along a current-carrying path.'),term('Strain relief','Support that prevents cable loads from being carried directly by a termination.'),term('Controlled impedance','A designed electrical property of a high-speed signal path.')],
  relatedIds:flight('01.04','02.03','05.01','07.04','08.01'),sourceIds:['flight-harness','flight-workmanship','flight-crisa','flight-spacewire','flight-quantum']
 },
 '08.01':{
  summary:'Flight avionics operate the spacecraft as a vehicle: they interpret commands, manage operating modes, collect health data and coordinate pointing, power and propulsion. GNSS navigation supplies position, velocity and timing information to the functions that need it.',
  sections:[
   sec('purpose','Keep vehicle authority separate from customer workloads',
    p('The customer-compute payload may execute large, changing jobs. The flight computer has a different responsibility: predictable control of the spacecraft and its interfaces. A payload restart should have a defined relationship to vehicle operation, rather than implicitly restarting navigation, power management or command handling. NASA’s avionics survey describes these architectural distinctions.','flight-avionics'),
    p('The allocation includes flight computing, a spacecraft recorder, protected command interfaces and navigation hardware. These functions may be integrated into one unit or distributed across several boxes. Moog’s Integrated Avionics Unit is a real example of combining command/data handling and spacecraft I/O; it does not identify the exact implementation installed here.','flight-iau')),
   sec('operation','Turn measurements into coordinated actions',
    p('Flight software receives sensor measurements, time tags events, estimates state and issues commands through defined interfaces. GNSS observations support navigation and timing, while attitude sensors establish orientation. Position and orientation are different states: knowing where the spacecraft is does not by itself tell an optical terminal which way it is pointing.'),
    p('A GNSS receiver also needs a suitable antenna view and mission-compatible operating envelope. NewSpace Systems’ Gemini products are real spacecraft navigation examples. Their product capability does not mean every orbit, antenna placement or workbench simulation is equivalent to a demonstrated receiver solution.','flight-gnss')),
   sec('engineering','Design for understood behavior under faults',
    p('Watchdogs, memory checking, controlled resets and redundant functions can support recovery, but they should serve a defined failure model. Critical state must be recoverable, commands must be validated, and the system needs a clear authority for entering protective operating modes. More processors do not automatically make those decisions coherent.'),
    p('Radiation-hardness evidence and software behavior complement one another. BAE Systems’ RAD750 is a real flight-computer family with documented mission use, while commercial payload processors represent a different performance and assurance trade. The study’s avionics mass and power allocation does not select a processor, operating system or demonstrated fault-tolerance architecture.','flight-rad750','flight-rha'))
  ],
  suppliers:[supplier('Moog','Integrated Avionics Unit','A real integrated spacecraft-avionics product reference; board selections and interfaces remain project decisions.','flight-iau'),supplier('BAE Systems','RAD750 single-board computers','A documented flight-computer family used to compare radiation-aware vehicle computing with customer accelerators.','flight-rad750'),supplier('NewSpace Systems','Gemini GPS/GNSS receivers and antennas','A real navigation-hardware family; mission and accommodation suitability still require verification.','flight-gnss')],
  alternatives:[alternative('Integrated avionics box','Combine several vehicle functions in one assembly.','Can simplify packaging while concentrating interfaces and shared resources.','flight-iau'),alternative('Distributed controllers','Place control electronics near equipment or functional domains.','Adds network, synchronization and authority-management requirements.','flight-avionics'),alternative('Higher-performance commercial processing','Use commercial devices where their performance justifies the assurance work.','Needs mission-specific radiation, recovery and environmental evidence rather than assuming server behavior carries over.','flight-hpe','flight-rha')],
  inspection:['Compare this allocation with the customer host-electronics page. The rendered enclosure represents a functional suite; it does not expose a selected processor board or navigation antenna installation.'],
  terms:[term('GNSS','Global navigation satellite system: a source of navigation and timing observations.'),term('Watchdog','A monitoring function that detects a missing expected response and can initiate recovery.'),term('State estimate','A calculated best estimate of variables such as position, velocity or orientation.')],
  relatedIds:flight('01.02','04.03','05.01','07.03','07.05'),sourceIds:['flight-avionics','flight-iau','flight-rad750','flight-gnss','flight-rha','flight-hpe']
 }
});

function mechanismArticle(hardware){
 const local=hardware?.energySystem?.thermal?.kind==='passive-local';
 return {
  summary:'Deployment and tracking mechanisms move large surfaces from a compact launch arrangement into their operating geometry. Release devices, hinges, actuators, springs, latches and position sensing perform different tasks within that sequence.',
  sections:[
   sec('purpose','Survive launch, then move deliberately',
    p('A solar wing or radiator needs restraint during launch and freedom to move afterward. The load path in the stowed state can differ from the deployed state. Release must occur at the intended time, and the moving structure must clear nearby hardware before it reaches its operating position. A complete sequence includes the hardware that holds, releases, drives and stops the motion.'),
    p(local?'The selected passive-local platform uses a spring-loaded deployment hinge in the reference concept. Electrical harnessing is part of that source accommodation; the additional bus thermal strap is a separate workbench assumption requiring its own hinge route. No pumped-fluid rotary crossing is installed for this platform.':'In the selected architecture, articulated radiator connections and their fluid interfaces must be considered alongside the mechanical joints. A hinge provides motion; it does not by itself preserve a pressure boundary or ensure that a routed cable survives repeated movement. Those interfaces have separate thermal and harness allocations.',local?'flight-redwire-thermal':'flight-iss-thermal')),
   sec('operation','Deployment and tracking are different motions',
    p('A deployment mechanism may move once into a latched geometry. A tracking drive may rotate repeatedly to follow a desired orientation. They can therefore have very different life, lubrication, torque and sensing requirements. Some arrays deploy using stored elastic energy: Redwire’s ROSA is a real example, so visible deployment does not imply a motor supplies every part of the motion.','flight-rosa'),
    p('Moog’s Type 2 solar-array drive illustrates a real rotary actuator with position information and electrical-transfer considerations. Continuous rotation may use slip rings; limited travel can use a suitably routed cable. The required electrical path and allowed rotation range should be specified together rather than discovered after the mechanism is packaged.','flight-sada')),
   sec('engineering','Allow margin for the installed assembly',
    p('Available drive torque must overcome friction, harness and fluid-line resistance, inertial demands and any latch or end-stop requirements. Ground tests also need to account for gravity differently from orbital operation. Large flexible surfaces can oscillate after motion, affecting attitude control and pointing even after the mechanism reaches its target angle.'),
    p('Position sensing should reveal the states the control system actually needs, including whether release and latching succeeded. Tolerances, thermal distortion and surface contact affect repeatability. NASA’s mechanisms survey and environmental-verification guidance are useful starting points; a smooth animation establishes the intended sequence, not deployment qualification.','flight-structure','flight-gevs'))
  ],
  suppliers:[supplier('Moog','Type 2 Solar Array Drive Assembly','A real tracking-drive reference with actuator and electrical-transfer interfaces. The workbench does not select its exact torque or slip-ring configuration.','flight-sada'),supplier('Redwire','ROSA','A real strain-energy deployment architecture for rollable arrays, distinct from a generic motor-driven rigid-panel hinge.','flight-rosa')],
  alternatives:[alternative('Stored-energy deployment','Use springs or elastic booms to deploy a surface.','Reduces continuous drive needs but still requires release, motion control and final-state assurance.','flight-rosa'),alternative('Motor-driven articulation','Command position through an actuator and transmission.','Adds power, sensing and mechanical life requirements.','flight-sada'),alternative('Fixed surface geometry','Avoid some deployment or tracking mechanisms.','Constrains launch packaging, orientation flexibility and available surface area.')],
  inspection:['Run deploy and stow to inspect the order of joints and clearance paths. The animation does not model friction, line strain, latch shock or flexible-body response.'],
  terms:[term('Hold-down and release','Hardware that restrains a structure for launch and frees it on command.'),term('Slip ring','An electrical connection that transfers circuits across a rotating joint.'),term('Latch','A device that holds a mechanism in a defined position.')],
  relatedIds:flight('02.01','03.01','03.02','04.01','07.05'),sourceIds:['flight-sada','flight-rosa','flight-structure','flight-gevs',local?'flight-redwire-thermal':'flight-iss-thermal']
 };
}

function adapterArticle(hardware){
 const rectangular=hardware?.payloadInterface?.attachmentShape==='rectangular-lugs';
 return {
  summary:'The launch adapter transfers spacecraft loads into the launch vehicle and provides the intended release boundary. Its structural shape, attachment pattern and separation mechanism must match both sides of the interface and the planned deployment sequence.',
  sections:[
   sec('purpose','Connect two independently designed vehicles',
    p('The spacecraft and launcher meet at a defined mechanical interface with agreed geometry, loads, mass properties and environmental requirements. An adapter can bridge different diameters or mounting patterns, but it cannot make arbitrary interfaces compatible by appearance alone. The launcher’s integration process establishes which configuration is accepted.','flight-falcon-guide'),
    p(rectangular?'The selected model uses an open cradle and a rectangular lug interface. Spacecraft-side corner lugs remain in the primary-frame allocation, while the lower attachment and launcher transition are counted here. The precise release hardware and provider acceptance remain open; a conventional ring datasheet is only a comparison for this geometry.':'The selected ring arrangement counts the active lower clamp, stand-off and launcher transition here. The passive upper ring stays with the spacecraft in the primary-frame allocation. Separating these mass boundaries prevents the same hardware from being counted twice when the launch stack and free spacecraft are compared.')),
   sec('operation','Restrain first, then create a clean separation',
    p('Before release, the interface must carry axial, lateral and dynamic loads while retaining the payload. The release mechanism then removes the restraint, and a defined separation action establishes relative motion. Springs, electrical disconnects and clearance geometry must be coordinated so no retained feature obstructs the departing spacecraft.'),
    p('Beyond Gravity offers real clamp-band and other separation-system configurations. Rocket Lab’s Motorized Lightband is a distinct ring-release reference. The relevant comparison is the complete system boundary—retention, release, push-off, shock, electrical interfaces and allowable loads—not only whether the product looks like a ring.','flight-separation','flight-lightband')),
   sec('engineering','Release conditions matter to the next mission phase',
    p('Separation velocity and tip-off rates affect the spacecraft’s initial acquisition and pointing task. Release shock can affect sensitive equipment, while connector forces and cable disengagement can influence the event. Flight software needs a defined understanding of when separation has occurred before it starts operations that depend on a free spacecraft.'),
    p('Verification should address the actual integrated load path and release configuration. The Falcon Payload User’s Guide illustrates how interface geometry, environments and integration requirements are documented for a real launcher family. Use the currently selected provider’s requirements for this mission; a generic animation and preliminary adapter mass do not establish approval for launch.','flight-falcon-guide','flight-gevs'))
  ],
  suppliers:[supplier('Beyond Gravity','Payload adapters and separation systems','A real manufacturer with multiple interface and release configurations. Its products are references, not a declaration that the selected study interface is procured or accepted.','flight-separation'),supplier('Rocket Lab','Motorized Lightband','A real motorized ring-release alternative. Suitability depends on its specific load, diameter and interface envelope.','flight-lightband')],
  alternatives:[alternative('Clamp-band interface','Distribute retention around compatible circular flanges.','Requires appropriate flange geometry, preload and release/shock characterization.','flight-separation'),alternative('Motorized ring release','Use a compatible electromechanical separation ring.','Changes actuation, power and verification requirements.','flight-lightband'),alternative('Point or lug attachments','Connect through discrete structural locations.','Concentrates loads locally and needs an explicitly designed release and clearance arrangement.','flight-separation')],
  inspection:['Inspect the boundary between the retained spacecraft fitting and launcher-side hardware. Use the launch integration sequence to see the intended release direction and nearby connectors.'],
  terms:[term('Tip-off','An angular rate imparted to the spacecraft during separation.'),term('Separation plane','The defined boundary where the departing spacecraft disconnects from retained hardware.'),term('Interface control','The agreed definition of geometry, loads, connections and responsibilities between systems.')],
  relatedIds:['flight:07.01','flight:08.01','launch:vehicle','ground:adapter','ground:fit'],sourceIds:['flight-separation','flight-lightband','flight-falcon-guide','flight-gevs']
 };
}
